insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'21767166-96f6-51f4-ba54-dda32288b6fe',E'Guía para la implementación de la Norma Técnica para la elaboración de Metadatos de los Procesos de Producción de Información Estadística y Geográfica',E'G-METADATOS',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Metadatos referenciales',E'Metadatos estructurales',E'Metadatos descriptivos']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/guia_implem_ntmppieg.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'da5dfe71-a58a-5d31-9b16-aac1709fbadb',E'Introducción · pág. 3',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Introducción\nInternacionalmente se ha reconocido que un factor importante para el uso correcto y exhaustivo de la\ninformación estadística y geográfica es contar con una estrategia institucional y directrices apropiadas para\nla preparación y difusión de metadatos.\nLos metadatos proporcionan a las personas usuarias información sobre los datos existentes, describiendo\nlos aspectos conceptuales y metodológicos sobre su captura, compilación, procesamiento y evaluación,\nasí como las formas de acceder a ellos, con la finalidad de que las personas usuarias puedan identificar,\nlocalizar y consultar los que atiendan de mejor manera sus necesidades. Los metadatos ayudan a las\npersonas usuarias a transformar los datos en información, de ahí la importancia de adoptar una\nterminología común y un conjunto de elementos estándar documentados con apego a normas bien\nestablecidas y de aceptación internacional.\nLa Norma Técnica para la elaboración de Metadatos de los Procesos de Producción de Información\nEstadística y Geográfica (Norma Técnica) establece las disposiciones generales y específicas para\nelaborar los metadatos de los Procesos de Producción de información estadística y geográfica mediante\nlos que se genera Información de Interés Nacional, con el propósito de favorecer su descripción\nestandarizada y estructurada.\nEn cumplimiento a lo establecido en el artículo 7 de la Norma Técnica, la Dirección General de Integración,\nAnálisis e Investigación (DGIAI) pone a disposición de las Unidades del Estado (UE) integrantes del SNIEG\nla presente Guía para la implementación de la Norma Técnica para la elaboración de Metadatos de\nlos Procesos de Producción de Información Estadística y Geográfica.</pre></div></section>',E'anexo',1,E'Guía de implementación · Norma Técnica de Metadatos',E'Introducción',E'Introducción',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'71f7ce98-ccdf-5057-a778-dabf77862049',E'Objetivo y glosario · pág. 4',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Objetivo de la Guía\nFavorecer el cumplimiento de las disposiciones específicas de la Norma Técnica y proporcionar a las\npersonas servidoras públicas responsables de la captura y autorización de metadatos, las descripciones,\ninstrucciones, contenido esperado, condición de llenado, aplicación y estándar de referencia para cada uno\nde los elementos que conforman las especificaciones de metadatos a los que hacen referencia los artículos\n4, 5 y 6 de la Norma Técnica, para conducir la elaboración de los metadatos de los Procesos de Producción\nde información estadística y geográfica.\nGlosario\nPara efectos de la presente Guía, además de lo establecido en el artículo 3 de la Norma Técnica, se entenderá\npor:\nAprovechamiento de grandes volúmenes de datos provenientes de entornos no controlados: utilización\ny transformación de múltiples tipos y fuentes de datos que se caracterizan por su alta dimensionalidad en\nrelación con las unidades de análisis;\nAprovechamiento de Registros Administrativos: utilización y procesamiento de datos sobre hechos o\nelementos existentes, cuyo registro es obligatorio para instituciones públicas o privadas;\nCenso: método de generación de información estadística, mediante la obtención de datos de cada uno de los\nelementos que conforman el conjunto objeto de estudio. En determinados contextos puede denominarse\ninventario;\nCiclo de Proceso: iteración de la ejecución de un Proceso; el cual puede ser de dos tipos:\n    a) Ciclo completo: aquel en el que se ejecutan las ocho fases del Proceso de Producción de Información\n       Estadística y Geográfica, Documentación de necesidades; Diseño; Construcción; Captación;\n       Procesamiento; Análisis de la producción; Difusión y Evaluación del proceso, y\n    b) Ciclo operativo:  aquel en el que se ejecutan las fases de Captación, de Procesamiento, de Análisis\n       de la Producción, de Difusión y de Evaluación del Proceso.\nClasificación: conjunto de categorías que pueden ser asignadas a una o más variables de un conjunto de\ndatos. Las categorías para cada nivel de la estructura de clasificación deben ser mutuamente excluyentes y\nen su conjunto exhaustivas, es decir, a cada una de las unidades de una población, territorio o fenómeno, se\nle puede asignar una y sólo una categoría;\nDDI: Estándar internacional basado en lenguaje XML para homologar el contenido, presentación y\npreservación de la documentación de los conjuntos de datos de estadística básica que permita el uso de los\ndatos de manera efectiva, eficiente y precisa (por sus siglas en inglés de la expresión Data Documentation\nInitiative);\nDominio de Estudio: subconjunto de la población para el cual se requiere realizar mediciones o\nrepresentaciones de los conceptos de forma separada;\nEncuesta no probabilística: la que emplea un proceso de selección basado en criterios determinísticos a\npartir de comportamientos conocidos o bien, de experiencias obtenidas en otros estudios similares;\nEncuesta por muestreo mixto:  la que se realiza con base en un esquema de muestreo combinado, es decir,\nemplea un diseño de muestreo no probabilístico para ciertos dominios de estudio y un diseño de muestreo\nprobabilístico para otros;\nEncuesta probabilística:  la que se realiza con base a un diseño que considera el componente aleatorio en\nla selección de las unidades que conforman la muestra;</pre></div></section>',E'anexo',2,E'Guía de implementación · Norma Técnica de Metadatos',E'Objetivo y glosario',E'Objetivo y glosario',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'fe002c74-32bd-5a01-90bc-d2c13ab06f28',E'Glosario · pág. 5',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Estructuración e integración de redes geométricas: modelado vectorial con topología de redes\ngeométricas de infraestructuras de conducción, a partir de levantamientos topográficos o la interpretación y\nextracción vectorial de imágenes satelitales. Incluyen redes de transporte, flujos de agua en ríos o arroyos,\ndistribución de agua potable, líneas eléctricas, conducción de gas, servicios telefónicos, entre otras;\nGeneración de índices de precios: cálculo de estimaciones sobre la variación de los precios desde un\nmomento determinado y para un periodo concreto;\nGeneración de información cartográfica: conjunto de actividades de gabinete y campo, por medio de las\ncuales se detectan, modelan y actualizan en la cartografía los rasgos físicos y culturales de interés en el\nterreno que sean objeto de cambios o creaciones;\nGeneración de información de estadística derivada: proceso caracterizado por la combinación de dos o\nmás fuentes de información con base en conceptualizaciones, reglas o metodologías diseñadas para fines\nespecíficos;\nGeneración de información de recursos naturales: procesamiento digital, análisis de imágenes y\nverificación de campo para la producción del inventario de recursos naturales del país;\nGeneración de información topográfica: abstracción de la realidad geográfica con propósitos generales y\nénfasis en propiedades geométricas (posición y/o forma) de objetos espaciales simbolizados;\nIndicador: medición que relaciona uno o más conceptos mediante la aplicación de una metodología sobre\nfenómenos de interés, que permite su análisis y sirve de base para el establecimiento de objetivos y metas,\nasí como para su seguimiento, desde el punto de vista de su magnitud, distribución y/o comportamiento en el\ntiempo y el espacio;\nIndicador-Objetivo: indicador asociado a un dominio de estudio y fenómeno de interés que permite hacer\nmediciones directamente relacionadas con los objetivos del Proceso de Producción. El indicador deberá\ncumplir al menos uno de los siguientes criterios: que derive del cumplimiento de una Ley o Reglamento; que\natienda un compromiso o recomendación internacional; que sea de utilidad para las políticas públicas; que\nforme parte de un conjunto de indicadores clave; o que contribuya a que la información sea comparable y\ncoherente a través del tiempo y con los componentes que lo conforman;\nISO: International Organization for Standardization (Organización Internacional de Normalización);\nLevantamientos geodésicos: el conjunto de procedimientos y operaciones de campo y gabinete destinados\na determinar las coordenadas geodésicas de puntos sobre el terreno considerando la curvatura de la Tierra,\nelegidos y demarcados con respecto al Sistema de Referencia en uso;\nNecesidad de Información: requerimiento de información expresada a través de una especificación legal,\nrequisito, solicitud u otra comunicación para la consideración de un productor de información;\nODS: Objetivos de Desarrollo Sostenible;\nProcesamiento de imágenes del territorio: tratamiento y análisis de imágenes de la superficie del terreno\ncapturadas por percepción remota, tanto de fotografías aéreas y vuelos LIDAR (Light Detection and Ranging),\ncomo de imágenes satelitales;\nProcesamiento geodésico especializado: tratamiento y análisis de datos geodésicos para producir y\nactualizar los marcos de referencia geodésicos; elaborar estrategias de mejora del modelo nacional de alturas,\ny controlar y mejorar el marco de referencia geodésico horizontal;\nSDMX: Estándar para el intercambio de datos y metadatos estadísticos; por sus siglas en inglés de la\nexpresión Statistical Data and Metadata eXchange;</pre></div></section>',E'anexo',3,E'Guía de implementación · Norma Técnica de Metadatos',E'Glosario',E'Glosario',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'bc14f23b-d219-515a-8bc3-abd646638e1d',E'Metadatos referenciales · pág. 6',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Territorio: la porción de la superficie delimitada geográfica, administrativa o políticamente perteneciente a la\nnación, a una entidad federativa, municipio o demarcación territorial;\nValor: cada uno de los números o modalidades nominales que puede admitir una variable;\nVariable: concepto que admite distintos valores para la caracterización o clasificación de un elemento o un\nconjunto, y\nVinculación de datos: conexión de datos a nivel unidad de observación o geográfica provenientes de\ndiferentes fuentes de información, mediante la utilización de identificadores equiparables.\nDescripciones, instrucciones, contenido esperado, condición de llenado, aplicación y estándar de\nreferencia de la especificación de metadatos referenciales para la descripción estandarizada de los\naspectos conceptuales, metodológicos y de calidad de los Procesos de Producción de información\nestadística y geográfica.\nA continuación, se detallan las descripciones, instrucciones, contenido esperado, condición de llenado,\naplicación y estándar de referencia y en algunos casos, ejemplos de documentación para cada uno de los\nelementos que conforman la especificación de metadatos referenciales incluidos en el Anexo I de la Norma\nTécnica el cual fue adaptado a partir de las especificaciones de Iniciativa de Documentación de Datos (DDI,\npor sus siglas en inglés) versión 2.0 y la estructura de metadatos del estándar SDMX para el Sistema\nEstadístico Europeo (ESMS) 2.0.\nPara documentar los metadatos existen elementos obligatorios, recomendados y opcionales. El llenado de los\nelementos obligatorios es indispensable para concluir la etapa de captura y edición, y continuar con la revisión,\nvalidación y autorización de los metadatos. Por otro lado, la documentación de los elementos recomendados\ny opcionales pueden incrementar significativamente el valor y utilidad de los metadatos.\nSección: Identificación del documento de metadatos.\nApartado: Creación o actualización del documento de metadatos.\nElemento: 1 PRODUCTOR DEL METADATO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Área administrativa responsable de la elaboración del metadato.\nContenido esperado: Nombre, abreviatura y afiliación de las Áreas Administrativas responsables de la\nelaboración del metadato.\nInstrucciones: Enlistar las Unidades Administrativas que intervienen en la elaboración del metadato, iniciando\npor la Unidad o Dirección General hasta nivel de Dirección de Área o equivalente.\nEjemplos:\n                            Nombre                                   Sigla        Dependencia\n  Unidad de Estadísticas Sociodemográficas                           UES             INEGI\n  Dirección General Adjunta de Encuestas Sociodemográficas          DGAES            INEGI\n  Dirección de Diseño Conceptual en Encuestas Especiales en        DDCEEH            INEGI\n  Hogares</pre></div></section>',E'anexo',4,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'208b9bcb-6762-500e-a732-9f2baa9bc572',E'Metadatos referenciales · pág. 7',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                            Nombre                                   Sigla        Dependencia\n  Dirección General de Industria, Energías Limpias y Gestión de la  DGIELGCA       SEMARNAT\n  Calidad del Aire\n  Registro Nacional Agrario                                          RAN            SEDATU\nEstándar de referencia: DDI CodeBook 2.0 (Responsible for the metadata, Metadata producer).\nElemento: 2 FECHA DE ACTUALIZACIÓN DEL METADATO\n                                    Condición de llenado: Obligatorio.\n                                    Aplicación: Todo tipo de Proceso de Producción.\nDescripción: Fecha de la última actualización de la documentación de metadatos.\nContenido esperado: Fecha de la última actualización de la documentación de metadatos.\nInstrucciones: Ingresar la fecha en formato DD/MM/AAAA. Este elemento deberá ser modificado con cada\nactualización del documento de metadatos.\nEjemplo: 19/11/2024.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Metadata last update); DDI CodeBook 2.0\n(Metadata preparation &gt; Date of production)\nElemento: 3 ACTUALIZACIÓN DE LOS METADATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Documentación de los cambios relevantes incorporados en cada nueva versión.\nContenido esperado: Número de versión, fecha y una breve descripción de los cambios relevantes\nefectuados a la documentación, a la base de datos o en el material de referencia del Proceso de Producción.\nInstrucciones: Indicar el número de versión, fecha, así como una breve descripción de los cambios relevantes\nefectuados a la documentación de metadatos.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción. Cuando exista más de una versión para un documento de metadatos, las diferentes versiones\ndeberán listarse en orden descendente.\nEjemplo: Versión 2 (1 de octubre 2021). Esta versión reemplaza la versión 1 (01 de enero de 2021) ya que\nincluye la actualización de las tasas de no respuesta.\nEstándar de referencia: DDI CodeBook 2.0 (Metadata preparation &gt; version).</pre></div></section>',E'anexo',5,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'4da3abd8-4cf1-52b3-b8d9-4fe8f2db8e77',E'Metadatos referenciales · pág. 8',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Sección: Proceso de producción documentado.\nApartado: Datos de identificación.\nElemento: 4 NÚMERO DE IDENTIFICACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todos los Procesos de Producción\nDescripción: Clave única alfanumérica que identifica al documento de metadatos de un determinado ciclo de\nProceso de Producción.\nElemento construido automáticamente por el sistema a partir de los elementos identificadores: (5) PROCESO\nDE PRODUCCIÓN, (7) CICLO DE PROCESO y (9) ÁREA RESPONSABLE DEL PROCESO DE\nPRODUCCIÓN.\nContenido esperado: Código alfanumérico único que identifica al metadato.\nInstrucciones: No es necesario capturarlo. Este elemento es construido en automático por el Sistema a partir\nde los elementos identificadores registrados al crear un documento de metadatos.\nEjemplos:\n      NTMPPIEG_INEGI_UEE-BCMM-2024-08\n      NTMPPIEG_INEGI_UES-ENOE-2024-04\n      NTMPPIEG_SNIEG_SEMARNAT-ISAO-2021\nEstándar de referencia: DDI CodeBook 2.0 (Document identification number).\nEstándar de referencia: DDI CodeBook 2.0 (Study).\nElemento: 5 PROCESO DE PRODUCCIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todos los Procesos de Producción\nDescripción: Nombre oficial del Proceso de Producción que se ejecuta para cumplir los objetivos y temas del\no los Programas de Información.\nContenido esperado: Nombre oficial del Proceso de Producción.\nInstrucciones: Indicar el nombre oficial del Proceso de Producción. No se deberán utilizar acrónimos ni\nabreviaturas.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nLas UE deberán hacer referencia al nombre del Proceso de Producción a partir del cual se genera la\nInformación de Interés Nacional.\nEjemplos:\n      Censo de Población y Vivienda\n      Encuesta Mensual de la Industria Manufacturera\n      Cuenta Satélite de Vivienda de México.\n      Encuesta Nacional sobre Uso del Tiempo\n      Agua Potable y Saneamiento.\n      Topografía Base</pre></div></section>',E'anexo',6,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'80211b7c-c7a2-5c62-9bd1-02b36c1f01a0',E'Metadatos referenciales · pág. 9',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">      Censo Nacional de Procuración de Justicia Estatal\n      Inventario de Sustancias Agotadoras de la Capa de Ozono.\nEstándar de referencia: DDI CodeBook 2.0 (Title of statistical project).\nElemento: 6 PROGRAMA DE INFORMACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todos los Procesos de Producción\nDescripción: Categoría que identifica los temas, conceptos o fenómeno a medir vinculados a la atención de\nlas necesidades de información. Bajo este enfoque, se reconoce que los Procesos de Producción pueden\ncontribuir a más de un Programa de Información\nContenido esperado: Listado de categorías que expresan las necesidades de información atendidas con la\nejecución del Proceso de Producción documentado.\nInstrucciones: Indicar la o las categorías temáticas que representan los Programas de Información a los\ncuales contribuye el Proceso de Producción documentado. No se deberán utilizar acrónimos ni abreviaturas.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEjemplos:\n      Proceso de Producción: Censo de Población y Vivienda.\n           o  Programas de Información: Población y demografía; Migración; Viviendas y entorno.\n      Proceso de Producción: Cuenta Satélite de Vivienda de México.\n           o  Programas de Información: Sistema de Cuentas Nacionales; Vivienda de México.\n      Proceso de Producción: Encuesta Nacional sobre Uso del Tiempo\n           o  Programas de Información: Uso del Tiempo; Trabajo; Género.\n      Proceso de Producción: Agua Potable y Saneamiento.\n           o  Programas de Información: Medio ambiente.\n      Proceso de Producción: Encuesta Nacional de Victimización y Percepción sobre Seguridad Pública.\n           o  Programas de Información: Instituciones de justicia; Confianza institucional; Violencia,\n              victimización y percepción de la seguridad pública.\n      Proceso de Producción: Información Estadística de los Puestos de trabajo registrados por los\n       patrones en el IMSS.\n           o  Programas de Información: Trabajo; Protección social.\nElemento: 7 CICLO DE PROCESO\n                                   Condición de llenado: Obligatorio\n                                   Aplicación: Todos los Procesos de Producción\nDescripción: Iteración de la ejecución del Proceso de Producción, regularmente asociada al periodo de\nreferencia o captación de la información.\nContenido esperado: Referencia temporal de la ejecución del ciclo de Proceso de Producción documentado.\nInstrucciones: Incorporar la referencia temporal de la ejecución del Proceso de Producción documentado.\nDeberá registrarse en formato numérico, en correspondencia con la Periodicidad de Producción de la\nInformación. Por ejemplo, ciclos anuales: AAAA; ciclos quincenales, mensuales, trimestrales, semestrales:\nAAAA-QQ; AAAA-MM; AAAA-TT; AAAA-SS.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.</pre></div></section>',E'anexo',7,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'2cc10138-8ed6-5434-94d5-71af7ea384fd',E'Metadatos referenciales · pág. 10',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Ejemplos:\nProceso de Producción con periodicidad quinquenal: Censos económicos, 2024.\nProceso de Producción con periodicidad trimestral: Encuesta Nacional de Ocupación y Empleo 2024-04.\nProceso de Producción con periodicidad mensual: Encuesta Mensual de Servicios 2024-12.\nProceso de Producción con periodicidad anual: Topografía Base, 2024.\nEstándar de referencia: No aplica. Este elemento fue incorporado en el marco del Modelo del Proceso\nEstadístico y Geográfico (MPEG).\nElemento: 8 SUBTÍTULO DEL DOCUMENTO DE METADATOS\n                                    Condición de llenado: Recomendado\n                                    Aplicación: Todos los Procesos de Producción\nDescripción: Información que amplíe o complemente ciertas limitaciones del nombre del Proceso de\nProducción.\nContenido esperado: Información complementaria al nombre del Proceso de Producción.\nInstrucciones: En caso necesario, incorporar información complementaria o referencias sobre el nombre del\nProceso de Producción que se va a documentar.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplos:\n      Nombre y ciclo del Proceso de Producción: Cuentas por Sectores Institucionales 2024.\n           o  Subtítulo: Datos anuales. Año base 2018=100.\n      Nombre y ciclo del Proceso de Producción: Encuesta Anual de Empresas Constructoras 2024.\n           o  Subtítulo: Serie 2018, datos de 2023.\n      Nombre y ciclo del Proceso de Producción: Encuesta Nacional de Ocupación y Empleo 2024-04.\n           o  Subtítulo: Cuestionario ampliado, datos correspondientes al tercer y cuarto trimestre.\n      Nombre y ciclo del Proceso de Producción: Inventario de Sustancias Agotadoras de la Capa de\n       Ozono 2021.\n           o  Subtítulo: Estadística del Consumo de Sustancias Agotadoras de la Capa de Ozono.\nEstándar de referencia: DDI CodeBook 2.0 (title and subtitle).\nSección: Características del proceso de producción.\nApartado: Productores de los procesos de producción.\nElemento: 9 ÁREA RESPONSABLE DEL PROCESO DE PRODUCCIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Unidad Administrativa responsable del Proceso de Producción.\nContenido esperado: Nombre, abreviatura y afiliación de las Áreas Administrativas responsables de la\nejecución del Proceso de Producción documentado.</pre></div></section>',E'anexo',8,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'f7a83a77-0447-57fa-8c82-398c094ee248',E'Metadatos referenciales · pág. 11',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Instrucciones: Enlistar las Áreas Administrativas responsables de la ejecución del Proceso de Producción\ndocumentado, iniciando por la Unidad o Dirección General hasta nivel de Dirección de Área o equivalentes.\nEjemplos:\n                             Nombre                                  Sigla        Dependencia\n     Unidad de Estadísticas Sociodemográficas                        UES              INEGI\n     Dirección General Adjunta de Encuestas Sociodemográficas       DGAES             INEGI\n     Dirección de Diseño Conceptual en Encuestas Especiales en     DDCEEH             INEGI\n     Hogares\n                             Nombre                                  Sigla        Dependencia\n     Dirección General de Industria, Energías Limpias y Gestión de  DGIELGCA       SEMARNAT\n     la Calidad del Aire\n     Oficina Nacional de Ozono                                       ONO           SEMARNAT\nEstándar de referencia: DDI CodeBook 2.0 (Authoring entity).\nElemento: 10 COLABORADORES\n                                    Condición de llenado: Recomendado\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Listado de otras UE, Órganos colegiados del SNIEG, instituciones, organizaciones, unidades o\náreas administrativas involucradas en el Proceso de Producción.\nContenido esperado: Nombre, abreviatura, afiliación y rol desempeñado por las Áreas Administrativas que\ncolaboran en la ejecución del Proceso de Producción documentado.\nInstrucciones: Enlistar las Áreas Administrativas que colaboran en la ejecución del Proceso de Producción\ndocumentado, iniciando por la Unidad o Dirección General hasta nivel de Dirección de Área o equivalentes.\nEjemplos:\n                 Nombre                   Sigla       Dependencia                Rol\n     Dirección de Encuestas Regulares     DERH           INEGI         Diseño del instrumento de\n     en Hogares                                                               captación\n     Dirección de Generación de          DGREE           INEGI         Análisis de la información\n     Resultados de Encuestas\n     Especiales\n                 Nombre                  Sigla        Dependencia                 Rol\n     Dirección General de Gestión      DGGIMAR         SEMARNAT         Verificación de las cuotas\n     Integral de Materiales y Actividades                               de importación anuales de\n     Riesgosas                                                          SAO\n     Dirección General de Planeación,  DGPPEE         Secretaría de     Procesamiento de datos\n     Programación y Estadística                     Educación Pública   en el Sistema de\n     Educativa                                                          Información y Gestión\n                                                                        Educativa\nEstándar de referencia: DDI CodeBook 2.0 (Other producers).\nElemento: 11 FINANCIAMIENTO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción</pre></div></section>',E'anexo',9,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'a1019c51-14db-5c86-b2ae-51d32a9108ae',E'Metadatos referenciales · pág. 12',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Descripción: Origen de los recursos necesarios para la ejecución del ciclo a documentar.\nContenido esperado: Tipo de financiamiento para la ejecución del ciclo de Proceso de Producción\ndocumentado.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEl tipo de financiamiento se deberá registrar de conformidad con las siguientes categorías:\n    a) Interno: si el total de los recursos necesarios para la ejecución de un Proceso de Producción proviene\n       de asignaciones presupuestales de la UE responsable.\n    b) Mixto: si la UE responsable recupera un porcentaje del costo de los recursos necesarios para la\n       ejecución de un Proceso de Producción, derivado de la celebración de un instrumento jurídico de\n       colaboración entre el Instituto y otra Unidad del Estado u organismo de los sectores público, privado,\n       social o académico, nacional o internacional.\nEstándar de referencia: DDI CodeBook 2.0 (Funding).\nApartado: Descripción general.\nElemento: 12 OBJETIVO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Descripción de los propósitos, alcance y principales usos previstos de la información generada\npor el Proceso de Producción.\nContenido esperado: Breve descripción del propósito, alcance y principales usos de la información generada\npor el Proceso de Producción documentado.\nInstrucciones: Describir brevemente el objetivo general y principales usos de la información del Proceso de\nProducción documentado.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEjemplos:\n      La Encuesta Nacional de Ocupación y Empleo (ENOE) es un esfuerzo realizado por el Instituto\n       Nacional de Estadística y Geografía (INEGI) para diseñar, levantar, procesar y difundir información de\n       las encuestas laborales, en el marco de la coordinación interinstitucional.\n      El Inventario de Sustancias Agotadoras de la Capa de Ozono tiene como objetivo verificar que el\n       consumo de Sustancias Agotadoras de la Capa de Ozono (SAO), considerado como la suma\n       algebraica de importaciones más producción menos exportaciones de SAO se ajusten a los límites\n       máximos de acuerdo con los calendarios establecidos en el Protocolo de Montreal.\nEstándar de referencia: DDI CodeBook 2.0 (Abstract, Description of scope); EURO-SDMX Metadata\nStructure 2.0 (Data description).\nElemento: 13 ANTECEDENTES\n                                    Condición de llenado: Recomendado</pre></div></section>',E'anexo',10,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'9577e37b-7138-5b38-a074-d7a4a2285394',E'Metadatos referenciales · pág. 13',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Breve descripción sobre los cambios o las mejoras realizados en los conceptos, la cobertura y\nlas metodologías con respecto a un Proceso de Producción anterior.\nContenido esperado: Principales antecedentes históricos, teóricos o metodológicos del Proceso de\nProducción documentado.\nInstrucciones: Incorporar una breve relatoría de los precedentes que dan sustento a la evolución conceptual\ny metodológica del Proceso de Producción documentado.\nEjemplos:\n      Encuesta Nacional de Ocupación y Empleo (ENOE): inició su levantamiento en 2005 y es la\n       consolidación y fusión de la Encuesta Nacional de Empleo Urbano (ENEU) y la Encuesta Nacional de\n       Empleo (ENE), que por más de dos décadas estuvieron proporcionando información de la población\n       ocupada y desocupada. Estas son resultado de una larga tradición de encuestas en hogares que inició\n       en 1972 con el levantamiento de la Encuesta Nacional de Hogares (ENH), en 1973 con la Encuesta\n       Continua de Mano de Obra (ECMO) y la Encuesta Continua Sobre Ocupación (ECSO);\n       posteriormente, de 1983 a 2004 la Encuesta Nacional de Empleo Urbano (ENEU) y de 1991 a 2004\n       la Encuesta Nacional de Empleo (ENE).\n      Inventario de Sustancias Agotadoras de la Capa de Ozono: a partir de la firma del Convenio de Viena\n       para la Protección a la Capa de Ozono, mediante publicación en el DOF Aprobación con fecha del 14\n       de septiembre de 1987, México adquiere el compromiso de implementar medidas y acciones\n       encaminadas a la protección de la capa de ozono. Un año más tarde, México también firma el\n       Protocolo de Montreal relativo a las Sustancias que Agotan la Capa de Ozono (SAO), mediante\n       publicación en el DOF Aprobación con fecha del 25 de enero de 1988. El Protocolo establece el listado\n       de las SAO o Sustancias Controladas, las Medidas de Control, el Control del Comercio, el\n       Incumplimiento, la diferenciación entre las Partes, Financiamiento, entre otros temas.\nEstándar de referencia: DDI CodeBook 2.0 (Series information).\nElemento: 14 MÉTODO DE GENERACIÓN DE LA INFORMACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Procedimientos específicos aplicados para la generación de información en los diferentes\nProcesos de Producción.\nContenido esperado: Método de la generación que corresponda al Proceso de Producción documentado.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda.\nÉste deberá identificarse de acuerdo con las siguientes categorías:\n      Aprovechamiento de grandes volúmenes de datos provenientes de entornos no controlados\n      Aprovechamiento de Registros Administrativos\n      Censo\n      Encuesta no probabilística\n      Encuesta por muestreo mixto\n      Encuesta probabilística\n      Estructuración e integración de redes geométricas\n      Generación de índices de precios\n      Generación de información cartográfica\n      Generación de información de estadística derivada</pre></div></section>',E'anexo',11,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'c7737ce1-1663-55cd-aab2-a108c86fdc64',E'Metadatos referenciales · pág. 14',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">      Generación de información de recursos naturales\n      Generación de información topográfica\n      Levantamientos geodésicos\n      Procesamiento de imágenes del territorio\n      Procesamiento geodésico especializado\n      Vinculación de datos\n      Otro\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEstándar de referencia:  DDI CodeBook 2.0 (Kind of data); EURO-SDMX Metadata Structure 2.0 (Data\nsource).\nElemento: 15 PERIODICIDAD DE PRODUCCIÓN DE LA INFORMACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Frecuencia con la que se ejecutan los ciclos de los Procesos de Producción.\nContenido esperado: Periodicidad definida para la ejecución del Proceso de Producción documentado.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda.\nSe deberá registrar de acuerdo con las siguientes categorías:\n      Diaria\n      Semanal\n      Quincenal\n      Mensual\n      Bimestral\n      Trimestral\n      Semestral\n      Anual\n      Bienal\n      Trienal\n      Cuatrienal\n      Quinquenal\n      Decenal\n      Otra\n      No determinada\n      Única\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEstándar de referencia: DDI CodeBook 2.0 &amp; EURO-SDMX Metadata Structure 2.0 (Frequency of data\ncollection).\nElemento: 16 GRADO DE MADUREZ\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Nivel de solidez metodológica y regularidad alcanzada por un Proceso de Producción para\natender un conjunto de necesidades de información.</pre></div></section>',E'anexo',12,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'13c5cfa3-c10a-5085-a128-b15c4da74340',E'Metadatos referenciales · pág. 15',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Contenido esperado: Grado de madurez del Proceso de Producción documentado.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEl grado de madurez deberá registrarse de conformidad a las siguientes categorías:\n      Experimental: Procesos de Producción que se ejecutan con el propósito de generar información para\n       atender temas emergentes o coyunturales, o bien para probar innovaciones metodológicas, fuentes\n       de información o modos de captación de datos. Algunos casos tendrán continuidad y eventualmente\n       evolucionarán en su grado de madurez, mientras que otros no requerirán la ejecución de ciclos futuros;\n      Institucionalizado: Procesos de Producción que generan productos con los que se atiende una\n       Necesidad Estructurada de Información, y\n      Consolidado y regular: Procesos de Producción institucionalizados que ejecutan ciclos con una\n       frecuencia definida, que asegura su continuidad. Estos Procesos podrán ser fuente de Información de\n       Interés Nacional conforme lo determine la Junta de Gobierno en términos de lo establecido en los\n       artículos 77, fracción II y 78 de la Ley del SNIEG.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEstándar de referencia: No aplica. Este elemento fue incorporado en el marco del Modelo del Proceso\nEstadístico y Geográfico (MPEG).\nElemento: 17 CONDICIÓN DE INFORMACIÓN DE INTERÉS NACIONAL\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Indicará si la información que el Proceso de Producción genera es Información de Interés\nNacional. Así mismo, se registrará la fecha de su determinación por parte de la Junta de Gobierno y, en su\ncaso, última actualización.\nContenido esperado: Condición de si la información generada a través del Proceso de Producción\ndocumentado es Información de Interés Nacional.\nInstrucciones: Seleccionar Sí o No.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEstándar de referencia: No aplica. Este elemento fue incorporado en el marco del Modelo del Proceso\nEstadístico y Geográfico (MPEG).\nElemento: 18 PALABRAS CLAVE\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción</pre></div></section>',E'anexo',13,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'13964d1a-4e05-5c58-ab55-b18078986697',E'Metadatos referenciales · pág. 16',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Descripción: Palabras o frases con orientación temática que describan aspectos sobresalientes del Proceso\nde Producción. Las palabras clave se usarán para facilitar la búsqueda de los documentos de metadatos de\nlos Procesos.\nSe deberá evitar incorporar palabras o frases que ya estén incluidas en el nombre del Proceso de Producción,\nasí como en el Título del documento de metadatos.\nContenido esperado: Palabras o frases que faciliten la búsqueda y consulta de los metadatos del Proceso\nde Producción.\nInstrucciones: Capturar separadas por comas palabras o frases con orientación temática sobre aspectos\nsobresalientes del Proceso de Producción documentado. No se deberán incluir palabras o conceptos ya\ncontenidos en el nombre del Proceso de Producción.\nEjemplos:\n      Palabras clave para la Encuesta Nacional de Ocupación y Empleo: actividad, condiciones, empresa,\n       salario, empleado, desempleo.\n      Palabras clave para el Inventario de Sustancias Agotadoras de la Capa de Ozono: SAO, HCFC, uso,\n       consumo.\nEstándar de referencia: DDI CodeBook 2.0 (Keywords)\nElemento: 19 PERIODO DE EJECUCIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Fechas previstas de comienzo y fin de las fases del Proceso de Producción.\nContenido esperado: Fechas de inicio y fin de las principales fases del Proceso de producción.\nInstrucciones: Indicar la fecha de inicio y fin de las principales etapas del Proceso de producción (planeación,\ndiseño, captación, procesamiento, difusión, etc.).\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplos:\nEncuesta Mensual de la Industria Manufacturera (EMIM), 2020. Datos al mes de mayo.\n                 Inicio         Fin                      Ciclo / Fase\n                2020-05       2020-06                     Mayo 2020\n              01-05-2020     30-05-2020                   Captación\n              18-05-2020     10-06-2020                 Procesamiento\n              11-06-2020     15-06-2020                    Análisis\n              15-06-2020     18-06-2020                    Difusión\nInventario de Sustancias Agotadoras de la Capa de Ozono, 2021\n               Inicio          Fin                       Ciclo / Fase\n             2021-12-01    2022-01-30                  Solicitud al SAT\n             2022-01-10    2022-01-10    Solicitud de datos a las empresas importadoras\n             2022-02-01    2022-02-15             Recepción de la información\n             2022-02-01    2022-03-15        Limpieza y verificación de la información\n             2022-03-01    2022-03-30              Análisis de la información\n             2022-04-01    2022-04-30            Generar e inviar el reporte final</pre></div></section>',E'anexo',14,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1bdf9ab5-58f1-5a99-a607-fa27d249c925',E'Metadatos referenciales · pág. 17',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Estándar de referencia: DDI CodeBook 2.0 (Dates of collection).\nApartado: Diseño conceptual.\nElemento: 20 POBLACIÓN OBJETO DE ESTUDIO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Identificación de los individuos, grupo de personas, unidades económicas, instituciones,\norganismos, territorio u otros elementos para la cual se requiere realizar mediciones o representaciones de\nlos conceptos; este conjunto contiene a todos los dominios de estudio.\nContenido esperado: Individuos, grupo de personas, unidades económicas, instituciones, organismos,\nterritorio u otros elementos que son el objeto de estudio del Proceso de Producción.\nInstrucciones: Indicar los individuos, grupo de personas, unidades económicas, instituciones, organismos,\nterritorio u otros elementos para la cual se requiere realizar mediciones o representaciones de los conceptos.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEjemplos:\n      ENOE: está dirigida a la población que reside permanentemente en viviendas particulares dentro del\n       territorio nacional. Para las características económicas, se captan datos de la población de 12 y más\n       años; aunque los indicadores que se difunden mensual y trimestralmente se generan para la población\n       de 15 y más años.\n      ISAO: 1. Importadores y exportaciones de Sustancias Agotadoras de la Capa de Ozono; 2.\n       Productores de Sustancias Agotadoras de la Capa de Ozono.\nEstándar de referencia: DDI CodeBook 2.0 (Universe); EURO-SDMX Metadata Structure 2.0 (Statistical\npopulation).\nElemento: 21 UNIDAD DE OBSERVACIÓN O DE ANÁLISIS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Representación del elemento o grupo de elementos de los cuales se recolectan o integran los\ndatos para generar la información que permita la caracterización adecuada del fenómeno o territorio objeto de\nestudio.\nContenido esperado: Unidad descrita por los datos para generar la información que permite la caracterización\nadecuada del fenómeno o territorio objeto de estudio.\nInstrucciones: Especificar las unidades de observación para las cuales se recolectan o integran los datos\npara generar la información.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEjemplos:</pre></div></section>',E'anexo',15,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'ebea7674-03d7-561a-a5bf-2847eb2894c3',E'Metadatos referenciales · pág. 18',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">      ENOE: La vivienda, el hogar y los integrantes del hogar.\n      ISAO: Importaciones, producción y exportaciones de las sustancias agotadoras de la capa de ozono.\nEstándar de referencia: DDI CodeBook 2.0 (Unit of Analysis); EURO-SDMX Metadata Structure 2.0\n(Statistical unit).\nElemento: 22 INDICADORES-OBJETIVO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Listado de los indicadores que sirven para conocer o cuantificar las características y la\nintensidad del fenómeno de interés relacionado directamente con los objetivos de un Proceso de Producción.\nContenido esperado: Listado de los principales indicadores asociados a un fenómeno de interés que\npermitan hacer mediciones directamente relacionadas con los objetivos del Proceso de Producción.\nInstrucciones: Enlistar los indicadores que dan a conocer y cuantifican las características y la intensidad del\nfenómeno de interés.\nEjemplos:\n      ENOE:\n           o  Condición de actividad económica: Población Económicamente Activa (PEA) y la Población\n              No Económicamente Activa (PNEA).\n           o  Condición de ocupación: Población ocupada y Población desocupada.\n           o  Condición de disponibilidad para trabajar: PNEA disponible y PNEA No disponible.\n           o  Experiencia laboral de los desocupados y PNEA.\n      ISAO:\n           o  Consumo de Sustancias Agotadoras de la Capa de Ozono.\nEstándar de referencia: No aplica. Este elemento fue incorporado en el marco del Modelo del Proceso\nEstadístico y Geográfico (MPEG).\nElemento: 23 DOMINIOS DE ESTUDIO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Subconjunto de la población objeto de estudio que está determinado por cuestiones temáticas,\ntemporales o geoespaciales.\nContenido esperado: Subconjuntos de la población, territorio o fenómeno para los cuales se requiere realizar\nmediciones o representaciones de los conceptos de forma separada.\nInstrucciones:  Listar los subconjuntos de la población objeto de estudio.\nEjemplos:\n     ENOE:\n              o   Total, hombres y mujeres\n              o   Población Ocupada\n                     o   Posición en la ocupación\n              o   Sector de actividad económica\n     ISAO:</pre></div></section>',E'anexo',16,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'7cdce1b1-4c4f-5932-aa0c-0b368c3e02c5',E'Metadatos referenciales · pág. 19',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">              o   Tipo de sustancia\n              o   Tipo de empresa\nEstándar de referencia: No aplica. Este elemento fue incorporado en el marco del Modelo del Proceso\nEstadístico y Geográfico (MPEG).\nElemento: 24 COBERTURA TEMÁTICA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Principales temáticas cubiertas por el Proceso de Producción.\nContenido esperado: Identificación del dominio temático asociado a los Subsistemas Nacionales de\nInformación, tomando en consideración la temática vinculada a cada uno según lo dispuesto en los artículos\n21, 24, 26, 27 y 28 Quáter de la Ley del SNIEG.\nInstrucciones: Mencionar las principales temáticas cubiertas por el Proceso de Proceso de Producción.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nA manera de sugerencia, se proporciona la siguiente lista de dominios temáticos:\n             Administraciones públicas                Instituciones de seguridad pública\n             Agricultura, ganadería y\n              aprovechamiento forestal                 Manufacturas\n             Áreas geoestadísticas                    Marco de Referencia Geodésico\n             Atmósfera                                Medio ambiente\n             Biodiversidad                            Migración\n             Calidad regulatoria y eficacia\n              gubernamental                            Minería\n             Calidad y condiciones de vida            Niñas, niños y adolescentes\n             Ciclos económicos                        Participación ciudadana\n             Ciencia, tecnología e innovación         Personas adultas mayores\n             Clima                                    Pesca y Acuicultura\n             Comercio                                 Población y demografía\n             Comercio internacional                   Pobreza\n             Confianza institucional                  Poderes Legislativos\n             Construcción                             Precios\n             Corrupción                               Protección social\n             Cultura                                  Recursos naturales\n             Derechos humanos                         Residuos\n             Desarrollo urbano                        Salud\n             Discriminación                           Servicios\n             Economía social y solidaria              Sistema de cuentas nacionales\n             Educación y capacitación                 Sistema penitenciario\n             Electricidad, gas y agua                 Suelo\n             Empresas y establecimientos,\n              multisectoriales                         Topografía\n             Finanzas públicas                        Trabajo</pre></div></section>',E'anexo',17,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1b111452-5310-5988-a0e0-fd4c039a19e5',E'Metadatos referenciales · pág. 20',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                                       Transparencia y acceso a la\n             Flora y Fauna                             información pública\n             Género                                   Transportes y movilidad\n             Gestión territorial                      Turismo\n             Imágenes del territorio                  Uso del tiempo\n             Información financiera                   Vías de comunicación\n             Ingresos, gastos, riqueza y              Violencia, victimización y percepción\n              finanzas de los hogares                   de la seguridad pública\n             Instituciones de justicia                Viviendas y entorno\nEjemplos:\n            Censo de Población y Vivienda: Características de la vivienda; Material en pisos; Número de\n             dormitorios; Número de cuartos; Disponibilidad de energía eléctrica; Disponibilidad de agua\n             entubada; Disponibilidad de sanitario; Admisión de agua al sanitario; Disponibilidad de drenaje;\n             Bienes; Tecnologías de la información y la comunicación.\n            ISAO: Atmósfera.\nEstándar de referencia: DDI CodeBook 2.0 (Topics classification).\nElemento: 25 ESTÁNDARES Y CLASIFICACIONES\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Mencionar el estándar, principio, recomendación, directriz, clasificación u otra referencia\nnacional o internacional que se haya consultado para desarrollar el marco o esquema conceptual del Proceso\nde Producción.\nContenido esperado: Estándares, recomendaciones nacionales e internacionales, clasificaciones o\ncatálogos utilizados en el diseño conceptual del Proceso de Producción.\nInstrucciones: Especificar los principales estándares, recomendaciones nacionales e internacionales,\nclasificaciones o catálogos en los que se sustenta el diseño conceptual del Proceso de Producción.\nEn caso de ser necesario los documentos listados podrán ser incluidos en los Materiales de Referencia\nExterno de la documentación de metadatos.\nEjemplos:\nENOE:\n      Informe de la XIII Conferencia Internacional de Estadísticos del Trabajo (CIET) de la Organización\n       Internacional del Trabajo (OIT), que trata el tema de las estadísticas de la población económicamente\n       activa, del empleo, desempleo y del subempleo.\n      Informe de la XIV CIET de la OIT, que aborda las estadísticas de ausencias del trabajo, incidencia de\n       los programas de promoción del empleo sobre la medición del empleo y el desempleo.\n      Clasificación de Parentescos, 2011.\n      Clasificación de entidades y países, 2012.\n      Catálogo de Dependencias e Instituciones de Interés Público (CADIIP), 2014.\nISAO:\n      Convenio de Viena para la Protección de la Capa de Ozono.\n      Protocolo de Montreal relativo al control de las Sustancias Agotadoras de la Capa de Ozono.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Classification system).</pre></div></section>',E'anexo',18,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'10e9d0be-4f41-5048-b115-4a78190a5177',E'Metadatos referenciales · pág. 21',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Elemento: 26 COBERTURA GEOGRÁFICA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Caracterización del espacio territorial o área geográfica a la que está referida la información que\nse produce y es empleada para su representación.\nPara el caso de la cobertura geográfica a nivel municipal o inferior, se deben indicar los cambios ocurridos en\nun área geoestadística con respecto al ciclo del Proceso de Producción inmediato anterior.\nContenido esperado: Espacio territorial o áreas geográficas del país representadas por los resultados del\nProceso de Producción.\nInstrucciones: Mencionar el espacio territorial o área geográfica a la que está referida la información\ngenerada por el Proceso de Producción.\nSe puede identificar con base en las siguientes categorías: nacional, estatal, municipal, demarcación territorial,\nlocalidad, área urbana o rural, ciudad, zona metropolitana y delimitaciones naturales.\nIndicar si es nacional, estatal, municipal, localidades urbanas y rurales, ciudades, delimitaciones naturales\ncomo pueden ser ecorregionales, provincias fisiográficas, acuíferos, cuencas, etc. Para el caso de la cobertura\ngeográfica a nivel municipal o inferior, se deben indicar los cambios ocurridos en un área geoestadística con\nrespecto al ciclo del Proceso de Producción inmediato anterior.\nEn el caso del INEGI, este campo se llenará en correspondencia con lo registrado en el Inventario de\nProgramas de Información.\nEjemplos:\n      Nacional, por entidad federativa.\n      Nacional, Estatal y Municipal.\n      Nacional, entidad federativa y ciudades auto representadas (Nacional urbano).\n      Para el XII Censo General de Población y Vivienda 2000, teniendo como referente al I Conteo de\n       Población y Vivienda 1995, en el Estado de Campeche el municipio 010 Calakmul se creó a partir de\n       los municipios 004 Champotón y 006 Hopelchén.\nEstándar de referencia: DDI CodeBook. 2.0 (Geographic Coverage); EURO-SDMX Metadata Structure 2.0\n(Reference area).\nElemento: 27 REPRESENTACIÓN ESPACIAL\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Aplica solo si el Proceso de Producción genera\n                                    conjuntos de datos espaciales\nDescripción: Método usado para la representación espacial de la información geográfica.\nContenido esperado: Categoría de representación espacial.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda.\nDeberá registrarse de conformidad con las siguientes categorías:\n•      Vector</pre></div></section>',E'anexo',19,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'60fd1d0f-f2b7-517f-9950-9f1d7bfc112e',E'Metadatos referenciales · pág. 22',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">•      Ráster\n•      Tabla del texto\n•      TIN\n•      Modelo estéreo\n•      Vídeo\nEstándar de referencia: ISO 19115-1:2014: 4.2 Tipo de representación espacial.\nApartado: Diseño muestral.\nElemento: 28 UNIDAD DE MUESTREO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Solo para Procesos de Producción que llevan a cabo\n                                    muestreo.\nDescripción: Elemento o conjunto de elementos que se seleccionan en las etapas del muestreo. La unidad\nde muestreo puede estar conformada por una unidad estadística o por un conjunto de unidades estadísticas\n(conglomerado).\nContenido esperado: Cualquiera de los elementos seleccionados de una población para constituir una\nmuestra.\nInstrucciones: Indicar el elemento o conjunto de elementos que se seleccionaron en la etapa de muestreo.\nEn caso de ser necesario hacer referencia de algún documento técnico, conceptual o metodológico, se deberá\nindicar el título del documento, así como el capítulo o sección donde se encuentra la información que se desea\nreferir. Preferentemente dicho documento deberá ser incluido en los Materiales de Referencia Externo de la\ndocumentación de metadatos.\nEjemplo: La vivienda particular.\nEstándar de referencia: DDI CodeBook 2.0 (Sampling procedure).\nElemento: 29 DISEÑO DE LA MUESTRA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Solo para Procesos de Producción que llevan a cabo\n                                    muestreo.\nDescripción: Descripción del esquema de muestreo utilizado por el Proceso de Producción. Indicar el\nprocedimiento de selección de la muestra y en el caso del muestreo probabilístico, los factores de expansión\ny los estimadores que se requieren para la generación de resultados.\nContenido esperado:\n1. Marco muestral.\n2. Tipo de muestreo.\n3. Formación, estratificación y distribución de las unidades de muestreo.\n4. Afijación, selección y, en su caso rotación de la muestra.\n5. Desviaciones del diseño muestral.\n6. Factores de expansión.\nInstrucciones: Indicar el procedimiento de selección de la muestra y en el caso del muestreo probabilístico,\nlos factores de expansión y los estimadores que se requieren para la generación de resultados.</pre></div></section>',E'anexo',20,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'98d7090f-6521-54ec-8da0-f91a2e203a47',E'Metadatos referenciales · pág. 23',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Este elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEn caso de ser necesario hacer referencia de algún documento técnico, conceptual o metodológico, se deberá\nindicar el título del documento, así como el capítulo o sección donde se encuentra la información que se desea\nreferir. Preferentemente dicho documento deberá ser incluido en los Materiales de Referencia Externo de la\ndocumentación de metadatos.\nEjemplos:\n      El tipo de muestreo utilizado por la Encuesta Nacional de Ocupación y Empleo (ENOE) es\n       probabilístico, bietápico, estratificado y por conglomerados. Probabilístico porque las unidades de\n       selección, es decir las viviendas, tienen una probabilidad conocida y distinta de cero de ser\n       seleccionadas.\n      El Inventario Nacional Forestal y de Suelos, mantiene para su segundo ciclo de muestreo 2009-2014,\n       un diseño estratificado sistemático por conglomerados en dos etapas, esta metodología sigue los\n       criterios establecidos en el Documento Estratégico Rector y asegura la consistencia en la\n       instrumentación de un nuevo periodo de medición, caracterización y monitoreo del recurso forestal.\nEstándar de referencia: DDI CodeBook 2.0 (Sampling procedure).\nElemento: 30 TAMAÑO DE LA MUESTRA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Solo para Procesos de Producción que llevan a cabo\n                                    muestreo.\nDescripción: Número de observaciones necesarias que se deben tener para poder dar estimaciones sobre\nuna población o variable.\nContenido esperado: Número de observaciones necesarias para que los datos obtenidos sean\nrepresentativos de la población objeto de estudio.\nInstrucciones: Indicar el número determinado de elementos seleccionados en el diseño muestral.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEn caso de ser necesario hacer referencia de algún documento técnico, conceptual o metodológico, se deberá\nindicar el título del documento, así como el capítulo o sección donde se encuentra la información que se desea\nreferir. Preferentemente dicho documento deberá ser incluido en los Materiales de Referencia Externo de la\ndocumentación de metadatos.\nEjemplos:\n      El tamaño de muestra de la Encuesta Nacional de Ocupación y Empleo (ENOE) se calculó con base\n       en la tasa de desocupación para ofrecer estimaciones a todos los niveles de cobertura geográfica de\n       la encuesta. Actualmente, el tamaño de muestra trimestral de la encuesta es de poco más de 126 mil\n       viviendas distribuidas en las trece semanas en las que se divide el trimestre.\n      Para el segundo ciclo de muestreo del INFYS, fue programada una malla de muestreo nacional para\n       su levantamiento en campo que representa un total de 24,889 conglomerados.\nEstándar de referencia: DDI CodeBook 2.0 (Sampling procedure).</pre></div></section>',E'anexo',21,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'eeb93d3e-193a-53ad-8981-8ad4bb537539',E'Metadatos referenciales · pág. 24',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Apartado: Captación de los datos.\nElemento: 31 PERIODO DE REFERENCIA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Fecha o periodo de tiempo al cual se refieren los datos del ciclo del Proceso de Producción.\nContenido esperado: Ciclo o tema y periodo de referencia de los datos captados.\nInstrucciones: Indicar las fechas o periodo de tiempo al cual se refieren los datos del ciclo del Proceso de\nProducción. La fecha deberá registrarse en formato DD-MM-AAAA o MM-AAAA o AAAA, según corresponda.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde.\nEjemplos:\n      ENOE 2024-02\n                 Inicio         Fin                      Ciclo o Tema\n              01-01-2024     31-03-2024             Primer trimestre de 2024\n              01-04-2024     30-06-2024            Segundo trimestre de 2024\n      ENVE 2024\n                 Inicio         Fin                      Ciclo o Tema\n              01-01-2023     31-12-2024                  Victimización\n              01-05-2024     30-06-2024       Percepción de la seguridad pública y\n                                                 desempeño de las autoridades.\n      ISAO 2023\n                 Inicio         Fin                      Ciclo o Tema\n              01-01-2023     31-12-2023                   ISAO 2023\nEstándar de referencia: DDI CodeBook. 2.0 (Time periods); EURO-SDMX Metadata Structure 2.0 (Reference\nperiod).\nElemento: 32 MODALIDAD DE CAPTACIÓN O RECOLECCIÓN DE LOS DATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Solo para Procesos de Producción que captan datos\n                                    directamente de las unidades de observación\nDescripción: Modalidad a través de la cual se captan los datos necesarios para generar los resultados del\nProceso de Producción.\nContenido esperado: Mecanismo o modalidad utilizada para la recolección de los datos.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. El modo de captación o\nrecolección de los datos deberá registrarse de conformidad con las siguientes categorías:\n      Entrevista directa asistida por dispositivo de cómputo móvil;\n      Entrevista directa con formato de captación en papel;</pre></div></section>',E'anexo',22,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'671372f6-2584-5fb6-83e0-3152440259f9',E'Metadatos referenciales · pág. 25',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">      Entrevista indirecta entregando formato de captación en papel;\n      Entrevista indirecta mediante llamada telefónica;\n      Extracción vectorial sobre ortoimágenes;\n      Formato de captación vía internet;\n      Formato de captación vía correo electrónico;\n      Formato de captación vía correo postal;\n      Integración de datos de diferentes fuentes;\n      Levantamientos geodésicos, topográficos y fotogramétricos;\n      Recorridos de campo;\n      Registros administrativos;\n      Percepción remota, y\n      Otro (especifique):\nEstándar de referencia: DDI CodeBook 2.0 (Mode of data collection); EURO-SDMX Metadata Structure 2.0\n(Data collection).\nElemento: 33 RESPONSABLE DE LA CAPTACIÓN DE LOS DATOS\n                                    Condición de llenado: Recomendado\n                                    Aplicación: Solo para Procesos de Producción que captan datos\n                                    directamente de las unidades de observación\nDescripción: Área administrativa responsable de la recolección de los datos. Esto se refiere a entidades que\nrecolectan los datos, no a las que procesan, analizan y difunden la información.\nContenido esperado: Identificación del área administrativa al interior de las UE que sea la responsable de la\nrecolección de los datos.\nInstrucciones: Indicar el nombre del área administrativa responsable de la recolección o captación de los\ndatos. Se debe diferenciar de aquellas que procesan, analizan y difunden la información.\nEjemplos:\n      INEGI, Unidad Estadísticas Sociodemográficas (UES).\n      SHCP, Servicio de Administración Tributaria (SAT).\n      SEMARNAT, Comisión Nacional Forestal (CONAFOR).\nEstándar de referencia: DDI CodeBook 2.0 (Data collectors).\nElemento: 34 DESCRIPCIÓN DEL INSTRUMENTO DE CAPTACIÓN\n                                    Condición de llenado: Recomendado\n                                    Aplicación: Solo para procesos de producción que captan datos\n                                    directamente de las unidades de observación\nDescripción: Descripción general del tipo, estructura, apartados o secciones del o los instrumento(s),\nformato(s) o sistema de captación de los datos.\nContenido esperado: Descripción del instrumento de captación utilizado para la recolección de los datos.\nInstrucciones: Documentar las características generales del instrumento de captación utilizado para la\nrecolección de los datos.\nPreferentemente, los instrumentos de captación deberán ser incluidos en los Materiales de Referencia Externo\nde la documentación de metadatos.</pre></div></section>',E'anexo',23,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'cb4e2d21-402c-5d3a-a408-bf7ca5056f73',E'Metadatos referenciales · pág. 26',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Ejemplos:\n      Para captar la información en la ENOE se utilizan el Cuestionario Sociodemográfico y el Cuestionario\n       de Ocupación y Empleo:\n           o  Cuestionario Sociodemográfico (CS) - Se aplica en todos los trimestres.\n           o  Cuestionario de Ocupación y Empleo (COE) - Ampliado (Primer trimestre de los años 2013 a\n              2020).\n           o  Cuestionario de Ocupación y Empleo (COE) - Básico (para los segundos, terceros y cuartos\n              trimestres de los años 2013 a 2020). La versión básica del COE consta de 90 preguntas\n              organizadas en nueve baterías con diferente temática:\n                  I.      Condición de ocupación\n                  II.     No ocupados\n                  III.    Contexto laboral\n                  IV.     Características de la unidad económica\n                  V.      Jornada y regularidad laboral\n                  VI.     Ingresos y atención médica\n                  VII.    Trabajo secundario\n                  VIII.   Búsqueda de otro trabajo\n                  IX.     Antecedentes laborales\n                  X.      Apoyos económicos\n                  XI.     Otras actividades\n      Los Formatos e instructivos de levantamiento de la información de campo por tipo de vegetación y\n       año de levantamiento del INFYS, precisan e ilustran las diferentes circunstancias y condiciones que,\n       de manera general, o incluso de manera excepcional, que pueden encontrarse en los diferentes\n       ecosistemas para la obtención de las variables de interés.\nEstándar de referencia: DDI CodeBook 2.0 (Type of research instrument).\nApartado: Procesamiento.\nElemento: 35 COMPILACIÓN DE DATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Solo para Procesos de Producción que no captan datos\n                                    directamente de las unidades de observación.\nDescripción: Listado de las fuentes y breve descripción de los mecanismos a través de las cuales se compilan\nlos datos para generar la información. Los datos pueden provenir de una mezcla de fuentes internas o\nexternas; así como de una variedad de modalidades de recolección.\nContenido esperado: Principales fuentes de datos y descripción del procedimiento para compilar datos de\nuna o más fuentes.\nInstrucciones: Indicar las principales fuentes de datos y el procedimiento implementado para compilar datos\nde fuentes externas.\nEn caso de ser necesario, se puede incorporar la referencia y el vínculo de acceso a algún documento de\nsoporte (especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEjemplo:\nA continuación, se efectúa un recuento de las fuentes de información empleadas para desarrollar esta\ninvestigación, que vendrá a enriquecer la disponibilidad de información y así coadyuvar al análisis del</pre></div></section>',E'anexo',24,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'05727c49-bf39-5607-86af-4c13b080b1b7',E'Metadatos referenciales · pág. 27',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">comportamiento económico de los agentes que operan en las distintas unidades institucionales en las que se\nha categorizado a la economía del país:\n      Sociedades financieras (Información de Estados financieros dictaminados, con las respectivas notas\n       a la información financiera del Banco Central, Sociedades depositarias, Fondos del mercado de\n       dinero, Fondos de inversión fuera del mercado de dinero, Otros intermediarios financieros, Auxiliares\n       financieros, Instituciones financieras cautivas y prestamistas de dinero, Sociedades de seguros,\n       Fondos de pensión, así como registros administrativos con información del sector asegurador, entre\n       otros).\n      Gobierno general (Cuenta pública, Cuenta de la hacienda pública federal, Clasificador por objeto del\n       gasto, Estados financieros, Analítico de ingresos, Presupuesto del gasto por partida, Presupuesto del\n       ramo 33 federal, Estado analítico del capítulo 4000 y 7000, Registros de transferencias otorgadas por\n       el Gobierno Federal a entidades educativas, protección social, y salud, Estadística de Finanzas\n       Públicas Estatales y Municipales, Análisis de Personal Ocupado, Estadísticas de población\n       derechohabiente, Desagregación de gastos de operación, Estado de variaciones al activo fijo,\n       Desagregación de construcciones por tipo de obra).\n      Hogares (Censos Económicos, Encuesta Nacional de Ingresos y Gastos de los Hogares, Encuesta\n       Nacional de Ocupación y Empleo, Cuenta de Bienes y Servicios).\nPara mayor detalle sobre cada una de las fuentes de información por sector institucional, se sugiere consultar\nel apartado 2.3.2 del documento Sistema de Cuentas Nacionales de México. Fuentes y metodologías, año\nbase 2013.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Source of data, Data compilation).\nElemento: 36 PROCESAMIENTO DE DATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Descripción general de los procedimientos de transformación de los datos captados o\ncompilados, tales como la clasificación, codificación, revisión, validación, edición e imputación de estos, para\nconvertirlos en información.\nContenido esperado: Breve descripción de las principales actividades correspondientes al procesamiento de\nlos datos.\nInstrucciones: Describir de forma general las actividades realizadas para el procesamiento de datos para\nconvertirlos en información. En caso de considerarlo necesario, se podrán mencionar las herramientas\ninformáticas o software utilizado para llevar a cabo el procesamiento de datos.\nPara los Procesos de Producción que no captan datos directamente de las unidades de observación, se\ndescribirá el procedimiento realizado para generar información a partir de estadísticas o datos geográficos\nprovenientes de una o varias fuentes, con apoyo en normas, reglas o métodos especializados.\nEn caso de ser necesario, se puede incorporar la referencia y el vínculo de acceso a algún documento de\nsoporte (especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEjemplos:\n      ENOE\n           o    Una vez concluida la etapa de captura de información, se recibe en oficina central los\n                archivos de captura de cada oficina estatal y se procede a integrar la base de datos de ese\n                levantamiento.</pre></div></section>',E'anexo',25,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'b1bc7119-1f99-5d62-9ef1-20620dacc056',E'Metadatos referenciales · pág. 28',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">           o    Generada la base de datos de los hogares y el cuestionario ampliado se envía al área de\n                marcos geoestadísticos que se encarga de generar los factores de expansión, corregidos\n                por la no respuesta.\n           o    Efectuada la última etapa de análisis de la información y con el factor de expansión agregado\n                a las bases, se procede a generar los indicadores y tabulados que conforman las distintas\n                publicaciones que se generan.\n      ISAO\n           o  Para el cálculo del consumo anual de SAO la SEMARNAT, a través de la DGIELGCA, solicita\n              a inicio de año al SAT todos los datos de importaciones de SAO registradas durante el año\n              inmediato anterior. Igualmente, la DGIELGCA solicita a cada empresa importadora que envíen\n              un informe de todos los movimientos de importación realizados en el año inmediato anterior.\n           o  Una vez que se cuenta con la sumatoria total para cada SAO se aplica la definición de\n              Consumo del Protocolo de Montreal. Es importante mencionar que para el caso particular de\n              las empresas que realicen exportaciones pueden solicitar a la DGIELGCA una Enmienda de\n              Asignación de Cuota para importar la misma sustancia en igual o menor cantidad a la\n              exportada, una vez que se demuestre la exportación de dicha cantidad a través de la\n              presentación de documentación certificada. El consumo debe de calcularse en kilogramos y\n              algunas sustancias, por la unidad de medida establecida en su fracción arancelaria, se\n              cuantifican en litros, por lo que para calcular su masa debe multiplicarse su volumen por la\n              densidad de cada sustancia.\nEstándar de referencia: DDI CodeBook 2.0 (Data Editing); EURO-SDMX Metadata Structure 2.0 (Data\ncompilation).\nElemento: 37 VALIDACIÓN DE DATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Descripción general de los mecanismos utilizados para depurar los conjuntos de datos como\nrevisiones de consistencia, chequeos aleatorios de datos, etcétera. Incluye la aplicación de criterios de\nvalidación de campo y las rutinas de captura que permitieron revisar los datos en cuanto a integridad,\nsecuencias, códigos válidos, congruencia básica, topología geográfica, completitud, exactitud, temática,\netcétera.\nContenido esperado: Descripción de los criterios y mecanismos de validación de datos implementados tanto\nen las etapas de captación, captura y procesamiento.\nInstrucciones: Describir de forma general las actividades realizadas para la validación de los datos con el\nobjetivo de garantizar el cumplimiento de los parámetros de calidad requeridos.\nDescribir de forma general las actividades realizadas para el procesamiento de datos para convertirlos en\ninformación.\nEn caso de ser necesario, se puede incorporar la referencia y el vínculo de acceso a algún documento de\nsoporte (especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEjemplos:\n      BCMM:\n       o   La discriminación de claves de pedimento aduanal, así como la aplicación de criterios estadísticos\n           diseñados para validar la información durante el proceso de generación de la estadística, permiten\n           asegurar la calidad de los resultados obtenidos. Se identifican y corrigen datos atípicos en el</pre></div></section>',E'anexo',26,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'9b3820d3-4b7d-5452-861b-12e309430c8e',E'Metadatos referenciales · pág. 29',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">           campo del tipo de cambio de pesos por dólares reportado en la base de datos, considerando como\n           base el tipo de cambio registrado por el Banco de México.\n       o   Se aplica la revaluación de las exportaciones de los principales productos agropecuarios y\n           pesqueros, operación que se lleva a cabo cuando los valores consignados para dichos productos\n           no corresponden con las cotizaciones del mercado internacional. Se incorporan registros\n           especiales que son recopilados directamente con las fuentes, como es el caso de las\n           exportaciones de petróleo reportadas por PMI Comercio Internacional S.A. de C.V. Las\n           operaciones comerciales de tipo triangular no se identifican.\n       o   Se identifican las operaciones que presentan niveles altos y considerablemente diferentes a los\n           observados en periodos previos, se realiza una investigación directa con las empresas\n           exportadoras e importadoras con la finalidad de verificar la veracidad de la información y en su\n           caso corregir el registro.\n      ISAO:\n           o  La información enviada por las empresas importadoras es validada contra los datos emitidos\n              por el SAT:\n                     Se verifica, clasifica y filtra el registro de cada SAO por Empresa.\n                     Se verifica el ingreso de la Aduana, éste se coteja con la autorización de la DGGIMAR.\n                     Se verifica que la sumatoria de la cantidad ingresada no rebase la cuota asignada del\n                      año para la empresa importadora.\n                     Se realiza la sumatoria para cada SAO.\nEstándar de referencia: DDI CodeBook 2.0 (Data Editing); EURO-SDMX Metadata Structure 2.0 (Data\nvalidation).\nElemento: 38 IMPUTACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Descripción del procedimiento o la técnica utilizada para la sustitución de valores perdidos o\nfaltantes, o bien, que sean inconsistentes con otros valores de la misma unidad de observación o la tendencia\nde otros conjuntos de datos de referencia.\nContenido esperado: Descripción del procedimiento o técnica utilizada para la imputación de datos.\nInstrucciones: Describir el procedimiento o técnica utilizada para la sustitución de valores faltantes o\ninadmisibles.\nSe deberá indicar los casos en los que no se llevan a cabo procesos de imputación de datos.\nEn caso de ser necesario, se puede incorporar la referencia y el vínculo de acceso a algún documento de\nsoporte (especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEjemplo:\nLa estimación del dato incoherente (no validada o corregida por el informante) o por la ausencia de este, se\nrealiza mediante la razón de días laborados en el mes inmediato anterior y los días calendario de este. El\nfactor obtenido se multiplica por los días calendario del mes a imputar.\nEstándar de referencia: DDI CodeBook 2.0 (Other processing).</pre></div></section>',E'anexo',27,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'88a6103c-a2d2-50c9-9eed-1dfe95bca1a6',E'Metadatos referenciales · pág. 30',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Apartado: Análisis.\nElemento: 39 ANÁLISIS DE DATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Descripción de las principales acciones realizadas o prácticas adoptadas para asegurar que la\ninformación generada es apta para su propósito, es decir, está lista para su uso y difusión.\nContenido esperado: Breve descripción de las principales actividades correspondientes al análisis y\nverificación de la información generada.\nInstrucciones: Describir de forma general las actividades realizadas para verificar la calidad de los resultados\nobtenidos. En caso de considerarlo necesario, se podrán mencionar las herramientas informáticas o software\nutilizado para llevar a cabo el análisis de datos.\nEn caso de ser necesario, se puede incorporar la referencia y el vínculo de acceso a algún documento de\nsoporte (especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEjemplos:\n      BCMM: Una vez obtenida la información agregada, se generan las series desestacionalizadas para\n       los grandes agregados de la BCMM y se verifica la calidad de los datos a través de un análisis de\n       cobertura, se comparan los resultados con la información histórica y se confronta con otras fuentes\n       de información tanto internas como externas. Una vez verificada la calidad de la información, el Banco\n       de México genera las cifras control lo que permite llevar a cabo la confronta de los resultados que se\n       obtienen con base en la información mensual y se procede a la distribución de las bases de datos a\n       las Unidades de Estado que participan en la generación estadística de la BCMM.\n      INFYS: Para respaldar la calidad y asegurar la confiabilidad del Inventario, se implementan controles\n       y actividades que incluye tres componentes principales: 1. Supervisión interna, como parte adicional\n       del levantamiento en campo las empresas deben contar con una brigada de supervisión interna\n       permanente que verificación en campo de la toma correcta de información, incluyendo, la\n       comprobación de la evidencia física del trabajo realizado por el muestreo; 2. Supervisión externa. La\n       Comisión Nacional Forestal puede ejecutar la supervisión en campo del 10 % o más si las condiciones\n       presupuestales lo permitieran, del total de los conglomerados levantados por las empresas\n       responsables del muestreo, 3. Revisión de gabinete que consiste en la validación de la congruencia\n       de los datos captados y de la información generada.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Data validation - Adjustment).\nApartado: Difusión.\nElemento: 40 RESULTADOS DISPONIBLES\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Listado de las presentaciones de resultados generados por el Proceso de Producción. También\nse deberá incluir la liga del sitio de consulta en Internet.\nContenido esperado: Listado y vínculo de consulta de las presentaciones de resultados generados por el\nProceso de Producción.</pre></div></section>',E'anexo',28,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'516fa709-e10f-597d-a118-9948f3fadaad',E'Metadatos referenciales · pág. 31',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Instrucciones: Enlistar el Nombre y URI de cada una de las presentaciones disponibles de los productos\nresultantes del Procesos de Producción.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplos:\n      ENOE\n                  Nombre                                       URI\n            Tabulados interactivos   https://www.inegi.org.mx/programas/enoe/15ymas/#Tabulados\n                Datos abiertos     https://www.inegi.org.mx/programas/enoe/15ymas/#Datos_abiertos\n      INFYS\n                          Nombre                                       URI\n            Sistema Nacional de Monitoreo Forestal         https://snmf.cnf.gob.mx/INFYS/\n               Principales indicadores forestales    https://snmf.cnf.gob.mx/datos-del-inventario/\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Publications).</pre></div></section>',E'anexo',29,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'caef13d5-da87-5e53-9bc2-89b59425478b',E'Metadatos referenciales · pág. 32',E'<section><p><strong>Nota de consulta:</strong> Anexo I: el diagrama de flujo y sus conexiones se consultan en el PDF original sincronizado. El texto siguiente es únicamente la transcripción de sus rótulos.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Elemento: 41 ESTATUS DE LA INFORMACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Diferentes estatus y criterios aplicados por la Unidad Administrativa responsable del Proceso\nde Producción para dar a conocer a las y los usuarios los cambios a la información divulgada en distintos\nmomentos en el tiempo.\nContenido esperado: Referencias y criterios aplicados por la Unidad Administrativa responsable del Proceso\nde Producción para dar a conocer a las y los usuarios los cambios en el estatus de la información divulgada.\nInstrucciones: Indicar los diferentes estatus y criterios aplicados por la Unidad Administrativa responsable\ndel Proceso de Producción para dar a conocer a las y los usuarios los cambios a la información divulgada.\nEn caso de ser necesario, se puede incorporar la referencia y el vínculo de acceso a algún documento de\nsoporte (especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEn el caso del INEGI, este campo se llenará conforme a los Lineamientos de Cambios a la Información\nDivulgada en las Publicaciones Estadísticas y Geográficas.\nEjemplos:\n      Las cifras preliminares se publican 22 días después del mes de referencia, de acuerdo con el\n       calendario anual aprobado por la Junta de Gobierno.\n      Las cifras definitivas se publican 45 días después del trimestre de referencia, de acuerdo con el\n       calendario anual aprobado por la Junta de Gobierno.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Data revision - policy)\nElemento: 42 CONDICIÓN DE ACCESO A MICRODATOS\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Modalidad de acceso a los microdatos, en cumplimiento con lo dispuesto en el marco regulatorio\nque corresponda de acuerdo con la naturaleza del Proceso de Producción.\nContenido esperado: Tipo de acceso a los microdatos del Proceso de Producción.\nInstrucciones: Seleccionar la condición de acceso a microdatos, de conformidad con las siguientes\ncategorías:\n      Descarga de archivos de uso público;\n      Archivos de datos con licencia de acceso;\n      Banco de datos o laboratorio de microdatos dentro de la UE responsable;\n      Microdatos disponibles en repositorio externo, y\n      Microdatos no disponibles.\nEjemplo: El acceso a Microdatos de las muestras de censos y conteos de población y vivienda, censos de\ngobierno y encuestas en hogares que genera el Instituto debe establecerse como Descarga de archivos de\nuso público.\nEstándar de referencia: DDI CodeBook 2.0 (Access Conditions); EURO-SDMX Metadata Structure 2.0\n(Microdata access).</pre></div></section>',E'anexo',30,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'e2e29cda-f268-54f9-b4be-8912cfc93597',E'Metadatos referenciales · pág. 33',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Elemento: 43 POLÍTICA DE CONFIDENCIALIDAD\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Legislación y disposiciones administrativas aplicables, relacionadas con la confidencialidad y\nprivacidad de datos de acuerdo con la naturaleza del Proceso de Producción.\nContenido esperado: Referencia de las disposiciones administrativas aplicables relacionadas con la\nconfidencialidad de la información.\nInstrucciones: Indicar la referencia a las disposiciones administrativas aplicables relacionadas con la\nconfidencialidad de la información.\nEn caso de ser necesario hacer referencia de algún documento técnico, conceptual o metodológico, se deberá\nindicar el título del documento, así como el capítulo o sección donde se encuentra la información que se desea\nreferir. Preferentemente dicho documento deberá ser incluido en los Materiales de Referencia Externo de la\ndocumentación de metadatos.\nEjemplos:\n      Esta encuesta se rige por las disposiciones de los artículos 37 y 47 de la Ley del Sistema Nacional de\n       Información Estadística y Geográfica. Toda información se mantendrá con carácter estrictamente\n       CONFIDENCIAL.\n      Artículo 37: Los datos que proporcionen para fines estadísticos los Informantes del Sistema a las\n       Unidades en términos de la presente Ley, serán estrictamente confidenciales y en ninguna\n       circunstancia podrán utilizarse para otro fin que no sea el estadístico. El Instituto no deberá\n       proporcionar a persona alguna, los datos a que se refiere este artículo para fines fiscales, judiciales,\n       administrativos o de cualquier otra índole.\n      El Registro Agrario Nacional para brindar certeza y seguridad jurídica a los sujetos agrarios solicita\n       los siguientes datos personales tanto del solicitante como del beneficiario: nombre completo, género,\n       domicilio, ocupación, estado civil, Clave Única de Registro de Población (CURP), números telefónicos\n       fijo y móvil, correo electrónico, los cuales serán destinados para: realizar las inscripciones en el\n       Registro y expedir las constancias que se soliciten; inscribir los actos jurídicos que señala el artículo\n       152 de la Ley Agraria y para conformar la información estadística, documental, técnica, catastral y de\n       planificación, que se establece en el artículo 154 de la Ley Agraria.\nEstándar de referencia: DDI CodeBook 2.0 (Confidentiality Declaration); EURO-SDMX Metadata Structure\n2.0 (Confidentiality - policy, Confidentiality - data treatment).\nElemento: 44 CONTACTO\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Sitio o cuenta de correo electrónico a la que las y los usuarios puedan referirse para dudas,\naclaraciones o peticiones especiales sobre el Proceso de Producción o sus productos.\nContenido esperado: Sitio o cuenta de correo electrónico de contacto para la atención de las y los usuarios\nde la información generada por el Proceso de Producción.\nInstrucciones: Proporcionar la cuenta institucional para la atención de las y los usuarios de la información.\nEn el caso del INEGI, el contacto deberá corresponder a la cuenta institucional.\nEjemplos:</pre></div></section>',E'anexo',31,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'19fe6b8c-438b-578d-8a93-70c6b131aed7',E'Metadatos referenciales · pág. 34',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">    o  INEGI. Atención a usuarios atencion.usuarios@inegi.org.mx\n    o  RAN. Subdirección de Certificación Documental e Historial Agrario interesnacional@ran.gob.mx\nEstándar de referencia: DDI CodeBook 2.0 (Contact Persons); EURO-SDMX Metadata Structure 2.0\n(Contact organization).\nApartado: Aseguramiento de la calidad.\nElemento: 45 EVALUACIONES IMPLEMENTADAS\n                                    Condición de llenado: Recomendado\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Mecanismos, criterios o procedimientos de evaluación de la calidad que han sido aplicadas al\nProceso de Producción.\nContenido esperado: Evaluaciones sobre la calidad de los datos implementados.\nInstrucciones:  Indicar cualquier mecanismo o ejercicio de evaluación de la calidad que han sido aplicadas\nal Proceso de Producción.\nPara la información generada por el INEGI, se debe hacer referencia a las evaluaciones realizadas\nconsiderando el Marco genérico de evaluaciones de calidad y a los indicadores aprobados por el Comité de\nAseguramiento de la Calidad.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplos:\n      Evaluación del proceso y plan de mejora (en el caso del INEGI, conforme a lo establecido en los\n       artículos 34 y 35 de la Norma Técnica del Proceso de Producción de Información Estadística y\n       Geográfica).\n      Herramienta para la Evaluación de la Calidad de los Registros Administrativos (HECRA).\n      Reports on the Observance of Standards and Codes (ROSCs).\n      Implementación y mantenimiento del Sistema de Gestión de la calidad de los INPC y del INPP de\n       conformidad con la Norma ISO 9001:2015.\n      Para respaldar la calidad y asegurar la confiabilidad del Inventario Nacional Forestal y de Suelos, se\n       implementan las siguientes actividades:\n           o  La colecta de datos del INFYS es realizada por proveedores de la CONAFOR que son\n              contratados a través de licitaciones públicas internacionales. Los documentos de las\n              licitaciones establecen los diversos requisitos que los proveedores deben cumplir, en materia\n              de control de calidad.\n           o  El manejo de la información parte de la base de datos del INFYS, fuente de información\n              primaria de la cual se derivan secciones que contienen variables organizadas de acuerdo con\n              el nivel del levantamiento en campo ya sea en la Unidad de Muestreo Primaria (UMP), en sus\n              4 Unidades de Muestreo Secundarias (USM), en los dos subsitios concéntricos que las\n              conforma o en el transecto localizado dentro una UMS.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Quality management &gt; Quality assurance,\nQuality assessment).\nElemento: 46 PERTINENCIA: USO DE LA INFORMACIÓN\n                                    Condición de llenado: Obligatorio</pre></div></section>',E'anexo',32,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'ff037895-a515-576c-8ed5-b9bbd1b83b2c',E'Metadatos referenciales · pág. 35',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Usos estratégicos de la información generada por el Proceso de Producción (mandato\nconstitucional, leyes, tratados internacionales, metas o indicadores del Plan Nacional de Desarrollo,\nindicadores de los Programas sectoriales o equivalentes, Indicadores Clave, Indicadores ODS; para el INEGI\ntambién se considera el Laboratorio de microdatos, consultas en el Portal del INEGI y utilización como insumos\nde otros procesos de producción).\nContenido esperado:  Principales usos estratégicos de la información generada por el Proceso de\nProducción.\nInstrucciones: Indicar el uso previsto o la motivación para la generación de la información resultante de la\nejecución de los Procesos de Producción.\nEn caso de que la fuente de la demanda sea un requerimiento legal, es necesario precisar el párrafo o número\ndel artículo, fracción, apartado o inciso.\nEjemplos:\n      ENOE\n                   Fuente                               Referencia\n          Plan Nacional de           Eje 2 Economía competitiva y generadora de empleos.\n          Desarrollo\n      INFYS\n                   Fuente                               Referencia\n          Ley General de Desarrollo  Sección 2. De la Comisión Nacional Forestal.\n          Forestal Sustentable\n          Programa Estratégico       Programas y acciones en materia forestal, diseño\n          Forestal para México 2025,  sobre la estrategia nacional sobre la reducción de\n                                     emisiones por la deforestación y degradación de los\n                                     bosques.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Relevance &gt; User needs).\nElemento: 47 ACCESIBILIDAD: INTERPRETACIÓN DE LA INFORMACIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Listado de los documentos conceptuales, metodológicos, glosarios, diccionarios de datos,\nesquemas entidad-relación, ediciones anteriores de metadatos entre otros recursos disponibles que faciliten\nel uso y la interpretación de la información generada por el Proceso de Producción.\nContenido esperado:  Documentos o recursos disponibles que faciliten el uso y la interpretación de la\ninformación generada por el Proceso de Producción.\nInstrucciones: Proporcionar el nombre, las URI de consulta o adjuntar los archivos de los recursos disponibles\nque faciliten el uso y la interpretación de la información del Proceso de Producción.\nEjemplos:\n      ENOE</pre></div></section>',E'anexo',33,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'b5ff19c1-d405-5ba7-ba61-70a859711f14',E'Metadatos referenciales · pág. 36',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                          Nombre                                    Archivo o URI\n           Cómo se hace la ENOE. Métodos y         https://www.inegi.org.mx/contenidos/productos/prod_s\n           procedimientos                          erv/contenidos/espanol/bvinegi/productos/nueva_estru\n                                                   c/702825190613.pdf\n      ISAO\n                          Nombre                                    Archivo o URI\n           Metodología   para  el  Consumo    de    Metodologia_Consumo_Nacional_SAO_24jun22.pdf\n           Sustancias Agotadoras de la Capa de\n           Ozono\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Accessibility and clarity &gt; Documentation on\nmethodology).\nElemento: 48 PUNTUALIDAD: INCORPORACIÓN EN CALENDARIO DE DIFUSIÓN\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Disponibilidad de las fechas de publicación de resultados en el calendario de difusión de la\ninstitución.\nContenido esperado: Condición de la incorporación de las fechas de publicación de resultados en el\ncalendario de difusión de la institución.\nInstrucciones: Su registro se debe realizar mediante las opciones Si o No. No aplica para los Procesos de\nProducción que se realizan bajo convenio, y que por las condiciones establecidas en el instrumento jurídico\nno se pueda preestablecer una fecha de publicación de resultados.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Release calendar).\nElemento: 49 PUNTUALIDAD: FECHAS DE PUBLICACIÓN COMPROMETIDAS\n                                    Condición de llenado: Recomendado\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: En caso de que las fechas de publicación de los resultados del Proceso de Producción, hayan\nsido inscritas en el calendario de difusión, indicar las fechas de la última publicación y de la próxima publicación\nde resultados.\nContenido esperado: Fecha de la última y de la próxima publicación de los resultados.\nInstrucciones: Documentar las fechas de publicación de resultados que contiene el calendario de difusión.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.</pre></div></section>',E'anexo',34,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1586b9c2-6a56-501b-b0bd-92be8396b75a',E'Metadatos referenciales · pág. 37',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Ejemplos:\n      ENOE\n            Resultados incluidos en el         Fecha de la última         Fecha de la próxima\n              calendario de difusión           publicación de los          publicación de los\n                                                   resultados                  resultados\n            Resultados trimestrales de la     15 de agosto de 2021      20 de noviembre de 2021\n                      ENOE.\n      ISAO\n            Resultados incluidos en el         Fecha de la última         Fecha de la próxima\n              calendario de difusión           publicación de los          publicación de los\n                                                   resultados                  resultados\n              Informe de Consumo de            30 de junio de 2023         28 de junio de 2024\n            Sustancias Agotadoras de la\n               Capa de Ozono, 2023.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Release calendar).\nElemento: 50 OPORTUNIDAD: PARÁMETRO DE REFERENCIA Y OPORTUNIDAD OBSERVADA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Número de días que transcurren entre el periodo de referencia del fenómeno de interés medido\ny la difusión de los resultados, tanto para el parámetro de referencia como para la oportunidad observada en\nel ciclo correspondiente.\nContenido esperado: Número de días transcurridos entre el periodo de referencia del fenómeno de interés\nmedido por el ciclo del Proceso de Producción documentado y la fecha de difusión de los resultados para el\nparámetro de referencia y para la oportunidad observada.\nInstrucciones: Documentar el número de días que transcurren entre el periodo de referencia del fenómeno\nde interés medido y la difusión de los resultados. Además, debe especificarse la fuente del parámetro de\nreferencia y si se retoma de mejores prácticas sobre recolección y difusión de información, norma o legislación\nnacional o internacional, recomendación internacional, política nacional o institucional, experiencia\ninternacional, práctica interna.\nPara la información generada por el INEGI, se debe capturar la información registrada en el Informe Anual de\nResultados del Comité de Aseguramiento de la Calidad.\nEjemplos:\n      Los resultados se difunden 44 días después de concluido el periodo de referencia del trimestre de\n       levantamiento. Parámetro de oportunidad: se investigó el caso de la difusión de los resultados\n       trimestrales de varios países (España, Chile, Colombia y Argentina) y la mayor oportunidad la tiene\n       España que difunde los resultados del trimestre 25 días después de que éste concluyó.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Timeliness).\nElemento: 51 COHERENCIA Y COMPARABILIDAD: COMPARABILIDAD TEMPORAL Y GEOGRÁFICA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción</pre></div></section>',E'anexo',35,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1601d52c-953f-5f4f-a431-5359955f3cc8',E'Metadatos referenciales · pág. 38',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Descripción: Grado de coherencia y comparabilidad de los datos del último ciclo publicado respecto a ciclos\nanteriores, explicando, de existir, los cambios en el diseño conceptual; sistemas de producción y flujos de\ntrabajo; diseño de la muestra; procesamiento y análisis de la producción.\nContenido esperado: Descripción del grado de coherencia y comparabilidad de los datos publicados en el\núltimo ciclo con respecto a los anteriores. En su caso, principales cambios al diseño del proceso de producción\ny consideraciones para el uso adecuado de los datos publicados.\nInstrucciones: Incluir el resultado del análisis de los datos, explicando, en su caso, las modificaciones al\ndiseño del Proceso de Producción respecto de ciclos previos, la coherencia y comparabilidad con\nobservaciones anteriores, así como resultados de las pruebas estadísticas. Indicar si existen elementos tales\ncomo series paralelas, retropolación de series históricas, tablas comparativas entre viejos y nuevos sistemas\nde clasificación, entre otros mecanismos que permitan la comparación de series de tiempo.\nLa información generada por el INEGI debe ser congruente con lo reportado en el Sistema de Seguimiento de\nCambios.\nEjemplos:\n      BCMM: Una vez obtenida la información agregada, se generan las series desestacionalizadas para\n       los grandes agregados, se verifica la calidad de los datos a través de un análisis de cobertura, se\n       comparan los resultados con la información histórica y se confronta con otras fuentes de información\n       tanto internas como externas.\n      INFYS: Uno de los principales procesos a realizar, es la revisión y aseguramiento de la calidad de los\n       datos, este proceso contempla los cambios en el levantamiento en campo a lo largo del ciclo de\n       muestreo analizado e incluso, de ciclos previos cuando se considere la comparación entre ellos para\n       la determinación de cambios en el tiempo.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Coherence and comparability &gt; Comparability\n-over time, Coherence - cross domain, Coherence - internal).\nElemento: 52 VERACIDAD: PRECISIÓN Y CONFIABILIDAD ESTADÍSTICA Y EXACTITUD GEOGRÁFICA\n                                    Condición de llenado: Obligatorio\n                                    Aplicación: Todo tipo de Proceso de Producción\nDescripción: Estimadores de precisión, confiabilidad y exactitud que se aplican, según el método de\ngeneración del Proceso de Producción.\nContenido esperado: Reporte de la precisión y confiabilidad estadística y exactitud geográfica de la\ninformación generada por el Proceso de Producción.\nInstrucciones: Describir las estimaciones e incorporar, en caso de aplicar, los indicadores de precisión y\nconfiabilidad estadística y exactitud geográfica que se aplican, según el método de generación del Proceso de\nProducción.\nPara la información generada por el INEGI, se deberán enlistar e incorporar los formatos de reporte de los\nindicadores aprobados por el Comité de Aseguramiento de la Calidad para evaluar la precisión y confiabilidad\nestadística y la exactitud geográfica, de conformidad con las fichas técnicas de dichos indicadores.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplos:</pre></div></section>',E'anexo',36,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'8958ec32-25d0-59a9-bfd2-e69abf17b3f0',E'Metadatos referenciales · pág. 39',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">      ENOE: Con el fin de ofrecer al usuario un elemento que le permita conocer la magnitud de los errores\n       asociados a las estimaciones, se calcularon sus errores estándar y coeficientes de variación, en el\n       entendido de que entre menor sea su valor, mayor es la precisión estadística del dato en cuestión. Así\n       mismo, se proporciona el número de observaciones muestrales obtenidas para cada categoría. De tal\n       manera que se califica como buena calidad si el coeficiente de variación no excede el 15 % y aceptable\n       si supera el 15 % pero no rebasa el 25 %; coeficientes mayores de 25 % son indicadores de\n       estimaciones de baja calidad. Por último, se presentan los límites del intervalo al 90 % de confianza\n       para el estimador, en primera instancia el inferior (LIIC), seguido del superior (LSIC).\n      INFYS: Para el segundo ciclo de muestreo del periodo 2015-2020, la tasa de respuesta fue del 90 %.\n       El porcentaje de conglomerados no muestreados por inaccesibilidad fue de 9.5 %, mientras que los\n       conglomerados no planeados para el muestreo representaron el 5 %.\n      ENCO: Los datos a nivel nacional muestran que en el 87.7 % de los casos se obtuvo resultado de\n       entrevista completa. La no respuesta totalizó 12.3 %, siendo 6.2 % corresponde al tipo A, el cual prevé\n       situaciones en las que no se logró la entrevista a pesar de la presencia de residentes en la vivienda;\n       5.3 % corresponde al tipo B, la característica principal de este tipo de no entrevista es que, al menos\n       durante el periodo de levantamiento, se corroboró que la vivienda seleccionada se encontraba\n       deshabitada; 0.3 % corresponde al tipo C, situaciones que afectan la muestra, y 0.5 % corresponde al\n       tipo D, levantamiento de la información completa del Cuestionario socioeconómico, pero sin levantar\n       la del Cuestionario básico.\n      A través de los siguientes vínculos se pueden consultar los indicadores de calidad sobre precisión y\n       confiabilidad estadística aprobados por el Comité de Aseguramiento de la Calidad del INEGI.\n                   Nombre del indicador                         Archivo del indicador\n           Coeficiente de variación, error estándar e         IPE_CV-EE-IC_ENOE_2024-\n           intervalo de confianza. ENOE 2024, primer            T1_Def_V1_190624.xlsx\n                          trimestre\n            Tasa de No Respuesta a nivel unidad de            IPE_TNRU_EFIPEM_2023-\n         observación. Estadística de Finanzas Públicas          00_Pre_V2_281124.xlsx\n                 Estatales y Municipales 2023\n            Tasa de No Respuesta a nivel variable.            IPE_TNRZ_EFIPEM_2023-\n          Estadística de Finanzas Públicas Estatales y          00_Pre_V2_281124.xlsx\n                      Municipales 2023\n         Sistema de aseguramiento y control de calidad  Sistema_de_Aseguramiento_y_Control_de_Ca\n        (SACC) en los proyectos de inventario forestal y            lidad_2019.pdf\n           de suelos de la Comisión Nacional Forestal\n         Exactitud de posicionamiento vertical. Marco de   MRG_Exactitud de posicionamiento\n                    referencia geodésico                             vertical.xlsx\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Accuracy and reliability &gt; Overall accuracy,\nSampling error, Non-sampling error).</pre></div></section>',E'anexo',37,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos referenciales',E'Metadatos referenciales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'4f1b511f-c353-55bf-bd77-5075ddebdf7d',E'Metadatos estructurales · pág. 40',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Descripciones, instrucciones, contenido esperado, condición de llenado y estándar de referencia de la\nespecificación de metadatos estructurales para la descripción estandarizada de los archivos de datos\nde los Procesos de Producción que generan información desagregada a nivel microdato.\nA continuación, se detallan las descripciones, instrucciones, contenido esperado, condición de llenado y\nestándar de referencia y en algunos casos, ejemplos de documentación para cada uno de los elementos que\nconforman la especificación de metadatos estructurales que se describen en el Anexo II de la Norma Técnica,\nlos cuales fueron adaptados a partir de la especificación de Iniciativa de Documentación de Datos (DDI, por\nsus siglas en inglés) versión 2.0.\nPara documentar los metadatos existen elementos obligatorios, recomendados y opcionales. El llenado de los\nelementos obligatorios es indispensable para concluir la etapa de captura y edición, y continuar con la revisión,\nvalidación y autorización de los metadatos. Por otro lado, los elementos recomendados y opcionales pueden\nincrementar el valor de los metadatos.\nSección: Archivos de base de datos.\nEsta sección aplica únicamente a los Procesos de Producción que generan bases de datos a nivel microdato\no cuyo método de generación de la información es Aprovechamiento de Registros Administrativos, Censo,\nEncuesta no probabilística, Encuesta por muestreo mixto o Encuesta probabilística.\nApartado: Descripción del archivo de base de datos.\nElemento: 1 NOMBRE DEL ARCHIVO DE BASE DE DATOS\n                                    Condición de llenado: Obligatorio\nDescripción: Nombre del archivo de la Base de datos o identificador de este recurso de datos.\nContenido esperado: Nombre de los archivos de las bases de datos documentadas.\nInstrucciones: Incluir el nombre para cada una de las bases de datos del ciclo del Proceso de Producción al\nque estén referidos los metadatos.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del\nProceso de Producción.\nEjemplos: COE1_TII2022, ISAO_2021, BD_INFS_2004-2009.\nEstándar de referencia: DDI CodeBook 2.0 (Data files &gt; name).\nElemento: 2 UNIDAD Y ÁREA ADMINISTRATIVA RESPONSABLE\n                                    Condición de llenado: Obligatorio\nDescripción: Área Administrativa responsable de la base de datos. El productor de la base de datos no es\nnecesariamente la Unidad y Área Administrativa responsable que recolectó o procesó los datos.\nContenido esperado: Nombre de la unidad o productor responsable de la base de datos.\nInstrucciones: Capturar el nombre de la Unidad y/o Área administrativa responsable del procesamiento de la\nbase de datos.\nEjemplo: INEGI, Unidad de Estadísticas Sociodemográficas (UES).\nEstándar de referencia: DDI CodeBook 2.0 (Data files &gt; producer).\nElemento: 3 SITIO DE DESCARGA DE LA BASE DE DATOS</pre></div></section>',E'anexo',38,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'9897206e-d65e-54f0-92cd-5bb988b8d8d8',E'Metadatos estructurales · pág. 41',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                    Condición de llenado: Recomendado\nDescripción: Vínculo o liga de consulta de las bases de datos, cuando el acceso a microdatos es de consulta\no descarga pública.\nContenido esperado: Vínculo de consulta o descarga de la Base de Datos documentada.\nInstrucciones: Indicar el vínculo de consulta o descarga de la base de datos, en caso de que sea de uso\npúblico.\nEjemplo: https://www.inegi.org.mx/programas/enoe/15ymas/#Microdatos\nEstándar de referencia: Data Catalog Vocabulary (DCAT): accessURL.\nElemento: 4 CONTENIDO DE LA BASE DE DATOS\n                                    Condición de llenado: Obligatorio\nDescripción: Descripción de la base de datos debiendo incluir: cobertura temática, características especiales\nde su contenido y principales variables.\nContenido esperado: Resumen del contenido de la base de datos.\nInstrucciones: Documentar brevemente las características del contenido de cada una de las bases de datos.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: Esta tabla almacena los rublos de identificación y la primera parte de las preguntas del cuestionario\nampliado, de los integrantes con entrevista completa.\nEstándar de referencia: DDI CodeBook 2.0 (Data files &gt; contents).\nElemento: 5 COBERTURA TEMPORAL\n                                    Condición de llenado: Obligatorio\nDescripción: Periodo de referencia de los datos contenidos en la base de datos, no a la fecha de creación o\npublicación.\nContenido esperado: Referencia temporal de la base de datos.\nInstrucciones: Indicar la referencia temporal de los datos contenidos en la base de datos. Fecha en formato\nDD/MM/AAA en la cual la base de datos se puso a disposición de las y los usuarios en su versión actual.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: Datos del segundo trimestre de 2022.\nEstándar de referencia: Dublin Core Metadata Initiative(coverage).\nElemento: 6 ÚLTIMA FECHA DE PUBLICACIÓN</pre></div></section>',E'anexo',39,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'e59c180e-b1ca-5d22-a4dd-89a496837136',E'Metadatos estructurales · pág. 42',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                    Condición de llenado: Recomendado\nDescripción: Fecha en la cual la base de datos se puso a disposición de las y los usuarios en su versión\nactual.\nContenido esperado: Última fecha de publicación de la base de datos.\nInstrucciones: Indicar la fecha en formato DD/MM/AAAA en la cual la base de datos se puso a disposición\nde las y los usuarios en su versión actual.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: 23/05/2022\nEstándar de referencia: Dublin Core Metadata Initiative (date).\nElemento: 7 VERSIÓN DE LA BASE DE DATOS\n                                    Condición de llenado: Recomendado\nDescripción: Descripción de cada versión de la base de datos. Se deberá incluir fecha y detalles de ajustes\nrealizados a la base de datos.\nContenido esperado: Descripción de los cambios implementados en cada versión de la base de datos,\nincluyendo cambios en el estatus de la información estadística y geográfica publicada.\nInstrucciones: Se deberá incluir fecha y detalles de ajustes realizados a la base de datos.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplos:\n      Segunda versión. El 23 de mayo de 2022, se reemplazaron los archivos de las Bases de datos debido\n       a que se actualizaron las estimaciones de población, con base en la propia actualización del Marco\n       de Muestreo de Viviendas del INEGI.\n      Tercera versión: Datos ajustados.\nEstándar de referencia: DDI CodeBook 2.0 (Data files &gt; version).\nElemento: 8 FORMATO DE LA BASE DE DATOS\n                                    Condición de llenado: Recomendado\nDescripción: Manifestación física o digital de la base de datos. Se deberá identificar la extensión del tipo de\narchivo con el fin de facilitar la identificación del software que se necesitaría para visualizar y/o explotar el\narchivo de base de datos.\nContenido esperado: Formato del archivo de la base de datos.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. Se deberá identificar la\nextensión del tipo de archivo con el fin de facilitar la identificación del software que se necesitaría para\nvisualizar y/o explotar el archivo de base de datos. Deberá registrarse de conformidad con las siguientes\ncategorías:</pre></div></section>',E'anexo',40,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'6b5d8124-a18e-5adf-ba7b-31d5ee4b32c2',E'Metadatos estructurales · pág. 43',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">             XLSX (archivos de Microsoft Excel)\n             DBF (Dbase File)\n             CSV (Comma-Separated Values)\n             SAV (Archivos de SPSS Statistics)\n             SAS (Archivos de Statistical Analysis Software)\n             CSPro (Census and Survey Processing System)\n             SHP (Esri shapefile)\n             Json\n             GeoJson\n             DWG\n             GPKG\n             GDB\n             Base de datos de Postgres y Postgis\n             Otro\nEstándar de referencia: Dublin Core Metadata Initiative (format).\nElemento: 9 FUENTE DE INFORMACIÓN\n                                    Condición de llenado: Obligatorio\nDescripción: Nombre completo o número de identificación del ciclo del Proceso de Producción del cual se\nderiva el contenido de la base de datos.\nContenido esperado: Proceso de Producción del cual se deriva el contenido de la base de datos.\nInstrucciones: Documentar el nombre y ciclo del Proceso de Producción.\nEjemplo: Encuesta Nacional de Ocupación y Empleo.\nEstándar de referencia: Dublin Core Metadata Initiative (source).\nElemento: 10 DERECHOS\n                                    Condición de llenado: Recomendado\nDescripción: Información sobre los derechos de propiedad intelectual del recurso de información. Puede\nincluir información sobre términos y condiciones de acceso a un recurso.\nContenido esperado: Información sobre los derechos de propiedad intelectual de la base de datos.\nInstrucciones: Indicar la referencia sobre la propiedad intelectual de la base de datos. En caso de ser\nnecesario, se puede incluir información sobre términos y condiciones de acceso a un recurso.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: Derechos reservados © INEGI 2022.\nEstándar de referencia: Dublin Core Metadata Initiative (rights).</pre></div></section>',E'anexo',41,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1c38edca-fe8b-54ca-9231-39efa41e94fc',E'Metadatos estructurales · pág. 44',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Elemento: 11 RELACIONES\n                                    Condición de llenado: Recomendado\nDescripción: Identificación de otros archivos de base de datos o recursos de información con los que se\npuedan relacionar con el recurso documentado. Se deberán mencionar las variables clave a través de las\ncuales es posible establecer las relaciones.\nContenido esperado: Archivos de BD que se relacionan con la base de datos documentada. Así como las\nvariables clave a través de las cuales es posible establecer dichas relaciones.\nInstrucciones: Para Procesos de Producción que cuenten con Bases de Datos relacionales se deben\nidentificar otras BD y/o recursos de información relacionados con la base de datos documentada. Así mismo,\nse deberán mencionar las variables clave a través de las cuales es posible establecer las relaciones entre BD.\nEstas relaciones deberán documentarse de conformidad con el Modelo Entidad-Relación.\nEjemplo: VIV_TII2022, HOG_TII2022, SDEM_TII2022, COE2_TII2022 a través de las variables Entidad,\nControl, Vivienda seleccionada y Tipo de entrevista.\nEstándar de referencia: Dublin Core Metadata Initiative (relation).\nElemento: 12 NOTAS O COMENTARIOS SOBRE LA BASE DE DATOS\n                                    Condición de llenado: Opcional\nDescripción: Información adicional acerca de la base de datos no cubierta en los puntos anteriores.\nContenido esperado: Información adicional acerca de la base de datos.\nInstrucciones: Documentar la información relevante y/o adicional que las y los usuarios necesiten saber sobre\nla base de datos.\nEjemplo: Para conocer algunas precisiones sobre la información y actualizaciones de archivos de las bases\nde datos aquí publicadas, se sugiere descargar el siguiente archivo:\nhttps://www.inegi.org.mx/contenidos/programas/enoe/15ymas/doc/enoe_notas_microdatos.pdf\nEstándar de referencia: DDI CodeBook 2.0 (Data files &gt; notes).\nSección: Documentación de Variables.\nEsta sección aplica únicamente a los Procesos de Producción que generan bases de datos a nivel microdato\no cuyo método de generación de la información es Aprovechamiento de Registros Administrativos; Censo;\nEncuesta no probabilística; Encuesta por muestreo mixto o Encuesta probabilística.\nApartado: Atributos y dimensiones.\nElemento: 13 NOMBRE DE LA VARIABLE\n                                    Condición de llenado: Obligatorio\nDescripción: Nombres o nemónico asignado a cada variable. Idealmente, los nombres de las variables\npueden contener, como máximo, entre 8 a 12 caracteres evitando utilizar símbolos o caracteres especiales, y\nusan un nombre lógico convencional.\nContenido esperado: Nombre de la variable.</pre></div></section>',E'anexo',42,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'df279836-1271-5c16-acaf-7ebc94fe034f',E'Metadatos estructurales · pág. 45',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Instrucciones: Idealmente, los nombres de las variables pueden contener, como máximo, entre 8 a 12\ncaracteres evitando utilizar símbolos o caracteres especiales, y usan un nombre lógico convencional. Por\nejemplo, la sección (S) y la pregunta (P) en el cuestionario pueden formar parte del nombre de la variable,\nS3P05 se refiere a la pregunta 5 de la sección 3 del cuestionario.\nEjemplos: ENT, VIV_SEL, CS_P13_1, V_1A1aActividadprincipal.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; name).\nElemento: 14 ETIQUETA\n                                    Condición de llenado: Obligatorio\nDescripción: Descripción corta y clara sobre el contenido o naturaleza de la variable.\nContenido esperado: Breve descripción sobre el contenido o concepto medido por la variable.\nInstrucciones: Indicar el nombre completo, el contenido o concepto medido por la variable.\nEjemplos: Entidad, Vivienda seleccionada, Nivel de instrucción, Actividad principal producción de electricidad\ny calor.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; label).\nElemento: 15 PROCESO DE PRODUCCIÓN\n                                    Condición de llenado: Recomendado\nDescripción: Referencia del Proceso de Producción del cual se origina la variable.\nContenido esperado: Ciclo de Proceso de Producción al cual pertenece la variable.\nInstrucciones: Indicar el ciclo de Proceso de Producción al cual pertenece la variable.\nEjemplo: Encuesta Nacional de Ocupación y Empleo.\nEstándar de referencia: No aplica. Este elemento fue incorporado en el marco del Modelo del Proceso\nEstadístico y Geográfico (MPEG).\nElemento: 16 VERSIÓN DE LA VARIABLE\n                                    Condición de llenado: Recomendado\nDescripción: Descripción de la versión de la variable. Se deberán incluir detalles de actualizaciones o\nmodificaciones realizadas, incluyendo los catálogos o los clasificadores utilizados.\nContenido esperado: Cambios implementados en cada versión de la variable.\nInstrucciones: Descripción de los cambios relevantes aplicados a la variable en relación con una versión\nanterior. Se deberán incluir detalles de actualizaciones o modificaciones realizadas, incluyendo los catálogos\no clasificadores utilizados.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: Versión 2, se actualizaron las categorías de la variable nivel de escolaridad.</pre></div></section>',E'anexo',43,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'b6066cf9-b6fc-5866-be61-78e1afa9a390',E'Metadatos estructurales · pág. 46',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Estándar de referencia: DDI CodeBook 2.0 (Variable description &gt; version).\nElemento: 17 LONGITUD DE VARIABLE (ANCHO)\n                                    Condición de llenado: Obligatorio\nDescripción: Máximo número de caracteres que pueden ser incluidos en una variable.\nContenido esperado: Número de caracteres que pueden ser incluidos en la variable documentada.\nInstrucciones: Se debe indicar el valor en número entero.\nEjemplo: La longitud de la variable edad es 3.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; width).\nElemento: 18 MÍNIMO\n                                    Condición de llenado: Recomendado\nDescripción: Corresponde al valor mínimo del rango de valores alcanzado.\nContenido esperado: Valor mínimo contenido en la variable documentada.\nInstrucciones: Se debe indicar el valor en número entero.\nEjemplo: Para la variable edad el valor mínimo es 0.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; range).\nElemento: 19 MÁXIMO\n                                    Condición de llenado: Recomendado\nDescripción: Este campo corresponde al valor máximo del rango de valores alcanzado.\nContenido esperado: Valor máximo contenido en la variable documentada.\nInstrucciones: Se debe indicar el valor en número entero.\nEjemplo: Para la variable edad el valor máximo es 130.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; width).\nElemento: 20 DECIMALES\n                                    Condición de llenado: Opcional\nDescripción: Número de los decimales implícitos para las variables numéricas que así lo requieran.\nContenido esperado: Número de los decimales implícitos para las variables numéricas.\nInstrucciones: Indicar el número de decimales que requieran las variables numéricas. Se debe indicar valor\nen número entero.</pre></div></section>',E'anexo',44,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'41ed3bba-2eb5-5e4c-9c27-791ac6c4bb59',E'Metadatos estructurales · pág. 47',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Ejemplo: para la variable kilómetros recorridos, se especifica que el número de decimales de los valores de\nla variable es 1.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; decimals).\nElemento: 21 TIPO DE VARIABLE\n                                    Condición de llenado: Obligatorio\nDescripción: Naturaleza de la variable en relación con su operatividad mediante la codificación de sus\nvalores. La clasificación del tipo de variable es importante porque repercute en el tipo de análisis que se\npueden realizar con los datos que contiene.\nContenido esperado: Tipo de variable.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. Deberá registrarse de\nconformidad con las siguientes categorías:\n            Nombre                                 Descripción\n                        Variables que son usadas para almacenar cualquier número, entero o\n         Numérica\n                        decimales.\n                        Variable que puede estar compuesta por letras, números y caracteres\n         Alfanumérica   especiales. En ocasiones algunas variables numéricas se clasifican\n         (cadena)       dentro de esta categoría debido a que utilizan ceros a la izquierda para\n                        su codificación cuando requieren una longitud fija.\n                        Las variables de tipo fecha se deben capturar en formato ISO (AAAA,\n         Fecha\n                        AAAA-MM, AAAA-MM-DD).\nEjemplos:\n      Variables numéricas: edad, ingresos, gastos, volumen de la producción, valor de la producción,\n       número de días transcurridos, asistentes a un evento.\n      Variables alfanuméricas: RFC, CURP, NSS, Entidad federativa cuando esta codificada a dos\n       caracteres (01, 02, 03, ...32).\n      Variables fecha: año de registro, fecha de nacimiento, periodo de referencia d ellos datos, fecha de\n       caducidad.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; data type).\nElemento: 22 MEDIDA DE LA VARIABLE\n                                    Condición de llenado: Obligatorio\nDescripción: Clasificación acordada con el fin de describir la naturaleza de la información contenida dentro\nde los números asignados a los valores de los registros de una variable.\nContenido esperado: Medida de la variable.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. Deberá registrarse de\nconformidad con las siguientes categorías:</pre></div></section>',E'anexo',45,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'25e1b845-f418-50f1-894f-760f0a278be2',E'Metadatos estructurales · pág. 48',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">           Nombre                                 Descripción\n                       Variables cualitativas con asignación de valores numéricos o numéricos\n                       restringidos que se denominan &quot;Categorías&quot;. El número asignado a cada\n            Nominal    categoría no tiene un significado por sí mismo. Estas variables requieren\n                       de la documentación de las etiquetas de cada categoría existente en el\n                       rango de valores de la variable.\n                       Variables continúas que tienen valores numéricos y no categóricos que\n                       cuantifican elementos. Pueden ser cuantitativas discretas cuando no puede\n            Escalar\n                       tomar ningún valor entre dos números consecutivos o cuantitativas\n                       continuas cuando pueden tomar cualquier valor dentro de un intervalo.\n                       Variables con asignación de valores numéricos que guardan un orden\n                       jerárquico, ordinal o de secuencia lógica ordenados según una escala\n            Ordinal\n                       preestablecida. En este tipo de variables el valor absoluto o la diferencia\n                       entre dos números no tienen significado.\nEjemplos:\n      Variable nominal: Sexo, donde 1 es el código para Hombres, 2 para mujeres y 9 para no especificado.\n      Variable escalar: Edad, donde los valores de los datos pueden ir de 0 a 130.\n      Variable ordinal: Clasificación o ranking de una competencia o evaluación, donde el valor 1\n       corresponde al primer lugar, 2 al segundo, 3 al tercero y así sucesivamente.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; measure).\nElemento: 23 CÓDIGOS Y ETIQUETAS DE CATEGORÍAS\n                                     Condición de llenado: Recomendado\nDescripción: Descripción o significado de cada uno de los valores de las variables nominales. Idealmente\ndeben estar basadas en listas de códigos estandarizadas, catálogos o clasificaciones comunes.\nContenido esperado: Descripción o significado de cada uno de los valores de las variables nominales.\nInstrucciones: Enlistar los códigos y etiquetas de las variables nominales.\nEjemplo:\n                  Código o valor        Etiquetas de las categorías\n                         1                       Hombre\n                         2                        Mujer\n                         9                   No especificado\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; category hierarchy).\nElemento: 24 DEFINICIÓN\n                                    Condición de llenado: Obligatorio\nDescripción: Descripción detallada de la variable; más completa que la provista por el nombre de la variable\ny su etiqueta. Se deberán describir los aspectos relativos al fenómeno, el concepto o la unidad de observación\nque mide la variable.\nContenido esperado: Descripción detallada del objetivo o propósito de la variable.</pre></div></section>',E'anexo',46,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'da15b0aa-8623-5855-8fbd-638812eefe3f',E'Metadatos estructurales · pág. 49',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Instrucciones: Se deberán describir los aspectos relativos al fenómeno, el concepto o la unidad de\nobservación que mide la variable.\nEjemplo:\n      Variable: Razón de no trabajar la semana pasada.\n      Definición: Identificar la razón principal por la que los ausentes no laboraron en la semana de\n       referencia.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; definition).\nElemento: 25 UNIVERSO\n                                    Condición de llenado: Obligatorio\nDescripción: Grupo de unidades, personas, objetos u otros elementos representados por la variable y a los\nque se refieren los datos. En general, debería ser posible establecer, a partir de la definición de la variable, si\nun individuo o elemento dado es un parte del universo de esta.\nContenido esperado: Personas, unidades, objetos u otros elementos que son el objeto de estudio de la\nvariable.\nInstrucciones: Indicar el grupo de unidades, personas, objetos u otros elementos al que se refieren los datos\ncontenidos en la variable. En general, debería ser posible establecer a partir de la definición de la variable, si\nun individuo o elemento dado (hipotético o real) es un parte del universo de esta.\nEjemplo: Todos los residentes de los hogares de 12 años y más.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; universe).\nElemento: 26 UNIDAD DE MEDIDA\n                                    Condición de llenado: Recomendado\nDescripción: Magnitud para la cual están asociados los valores medidos. Especificar si se refiere a unidades\nfísicas, por ejemplo: personas, horas, pesos, dólares, miles de pesos, hectáreas, etcétera.\nContenido esperado: Unidad para la cual están asociados los valores medidos.\nInstrucciones: Especificar si se refiere a unidades físicas.\nEjemplo: personas, horas, pesos, dólares, miles de pesos, hectáreas, etcétera.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Unit of measure).\nElemento: 27 CRITERIO DE VALORACIÓN DE LA UNIDAD DE MEDIDA\n                                    Condición de llenado: Recomendado\nDescripción: Referencias necesarias para la correcta interpretación de la unidad de medida.\nContenido esperado: Referencias necesarias para la correcta interpretación de la unidad de medida.\nInstrucciones: Para las variables económicas indicar si se trata de precios constantes, valores corrientes,\ncosto de adquisición, valores netos o brutos, etcétera.</pre></div></section>',E'anexo',47,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'24eda689-640c-5ea1-9714-b6575c82a076',E'Metadatos estructurales · pág. 50',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Ejemplo: Para el caso de una variable que contiene el valor de la producción, se deberá especificar si la\nunidad de medida Millones de pesos, corresponde a &quot;precios constantes&quot; o &quot;precios corrientes&quot;.\nEstándar de referencia: EURO-SDMX Metadata Structure 2.0 (Unit of measure).\nElemento: 28 INFORMANTE\n                                    Condición de llenado: Recomendado\nDescripción: Persona que se identifica como “informante adecuado” para proporcionar la información\ncontenida en la variable. Se deberá identificar si se trata de un informante directo e indirecto.\nContenido esperado: Persona que se identifica como “informante adecuado” para proporcionar la\ninformación contenida en la variable.\nInstrucciones: Se deberá identificar si se trata de un informante directo e indirecto.\nEjemplo: Cualquier persona de 15 años o más que sea residente habitual del hogar.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; source of information).\nElemento: 29 PREGUNTA EN EL INSTRUMENTO DE CAPTACIÓN\n                                    Condición de llenado: Recomendado\nDescripción: Texto literal tal cómo se solicita la información en el instrumento de captación. Este elemento\nno aplica a todas las variables y tiene como finalidad comprender cómo fueron realizadas las preguntas en la\nentrevista o cómo están diseñados los campos de llenado.\nContenido esperado: Pregunta literal contenida en el instrumento de captación.\nInstrucciones: Indicar la pregunta textual contenida en el instrumento de captación.\nEste elemento no aplica a todas las variables y tiene como finalidad comprender cómo fueron realizadas las\npreguntas en la entrevista o cómo están diseñados los campos de llenado.\nEjemplo: ¿Cuál es la razón principal por la que… no trabajó la semana pasada?\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; literal question).\nElemento: 30 INSTRUCCIONES PARA EL ENTREVISTADOR\n                                     Condición de llenado: Recomendado\nDescripción: Indicaciones contenidas en los manuales o instructivos para la captación de la información. Se\ndeben incluir instrucciones previas o posteriores a la pregunta, indicaciones sobre las posibles respuestas, la\nforma de hacer la pregunta o llenar un formato de captación.\nContenido esperado: Indicaciones contenidas en los manuales o instructivos para la captación de la\ninformación.\nInstrucciones: Se deben incluir instrucciones previas o posteriores a la pregunta, indicaciones sobre las\nposibles respuestas, la forma de hacer la pregunta o llenar un formato de captación. Este elemento no aplica\na todas las variables.</pre></div></section>',E'anexo',48,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'e318c183-b686-5fe4-8ccd-0bbd9e77b649',E'Metadatos estructurales · pág. 51',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Ejemplo: Escucha y circula la opción indicada por el informante. Si circulas una de las opciones de 01 a 04,\npasa a la pregunta 3. Si circulas la opción 11, pasa a la pregunta 2.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; interviewer instructions).\nElemento: 31 PALABRA(S) CLAVE(S) PARA BÚSQUEDA DE LA VARIABLE\n                                    Condición de llenado: Obligatorio\nDescripción: Palabras o frases con orientación temática que describan el contenido de una variable. Se\nrecomienda el uso de vocabularios controlados y de sistemas de clasificación formales.\nContenido esperado: Palabras o frases que ayuden a la búsqueda y recuperación de la variable.\nInstrucciones: Capturar separadas por comas palabras o frases con orientación temática sobre aspectos\nsobresalientes de la variable. No se deberán incluir palabras o conceptos ya contenidas en el nombre y\netiqueta de las variables.\nSe recomienda el uso de vocabularios controlados y de sistemas de clasificación formales.\nEjemplo: incapacidad, empleados, ausentes.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; keywords).\nElemento: 32 DATOS PERDIDOS\n                                    Condición de llenado: Recomendado\nDescripción: Descripción de la codificación utilizada para la identificación de los valores correspondientes a\nlos datos perdidos. Los datos perdidos corresponden a casos en los que no existe información para algunas\nunidades de observación (registros) cuando si son parte del universo o de la población objeto de estudio de la\nvariable, estos casos debieran estar codificados con algún código específico.\nContenido esperado: Codificación utilizada para la identificación de los valores correspondientes a los datos\nperdidos.\nInstrucciones: Indicar la codificación utilizada para la identificación de los datos perdidos, de acuerdo con la\nlongitud de la variable (elemento 17 de esta sección).\nEjemplos:\n      9 - No especificado\n      99 - No sabe o no responde\n      999 - No aplica\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; missing values).\nElemento: 33 IMPUTACIÓN\n                                    Condición de llenado: Recomendado\nDescripción: Proceso utilizado para imputar valores o datos perdidos que han sido recuperados y\nreemplazados en los registros de la variable.</pre></div></section>',E'anexo',49,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'89d4c8b4-6fed-5f64-851f-46678759ecd8',E'Metadatos estructurales · pág. 52',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">En caso de ser necesario, se puede incorporar la referencia y vínculo de acceso a algún documento de soporte\n(especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nContenido esperado: Descripción del método o mecanismo utilizado para la imputación de los valores o\ndatos perdidos que han sido recuperados y reemplazados en los registros de la variable.\nInstrucciones: Describir brevemente el método o mecanismo utilizado para imputar valores o datos perdidos.\nEn caso de ser necesario, se puede incorporar la referencia y vínculo de acceso a algún documento de soporte\n(especificando capítulo, apartado y número de páginas) en donde se describan los detalles de dicho\nprocedimiento.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: Para la variable Valor del consumo de envases y empaques, se calcula la participación de la variable\nen el valor de producción del año anterior. Posteriormente se aplica dicha participación al valor de producción\nestimado, también se le aplica la estructura del año anterior para calcular la distribución según el origen. De\neste modo damos a estos gastos el mismo comportamiento del valor de producción.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; imputation).\nElemento: 34 RECODIFICACIÓN Y DERIVACIÓN\n                                    Condición de llenado: Recomendado\nDescripción: Descripción del proceso o algoritmo utilizado para derivar las variables que no fueron obtenidas\ndirectamente de la fase de captación, o de datos que se obtuvieron por recodificación de las variables\noriginales, incluyendo la codificación de variables captadas en texto abierto. En caso de ser necesario, se\npuede incorporar la referencia y vínculo de acceso a algún documento de soporte (especificando capítulo,\napartado y número de páginas) en donde se describan los detalles de dicho procedimiento.\nContenido esperado: Documentación del método o mecanismo utilizado para la recodificación o derivación\nde variables.\nInstrucciones: Describir brevemente el método o mecanismo utilizado para recodificar o crear nuevas\nvariables a partir de las captadas de origen. En caso de ser necesario, se puede incorporar la referencia y\nvínculo de acceso a algún documento de soporte (especificando capítulo, apartado y número de páginas) en\ndonde se describan los detalles de dicho procedimiento.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: La variable Edad agrupada (EDAD_GRP) fue obtenida por recodificación de la edad en años provista\nen la variable EDAD en grupos de edad 0-4, 5-9…65 y más”. Se excluye el código 999 correspondiente a la\nedad no especificada.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; coding instructions).\nElemento: 35 NIVEL DE ACCESO A LA VARIABLE\n                                    Condición de llenado: Recomendado\nDescripción: Información sobre el nivel de acceso a la variable en correspondencia con el método de\ngeneración del Proceso de Producción y en cumplimiento con lo dispuesto en el marco regulatorio que\ncorresponda.</pre></div></section>',E'anexo',50,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'cc65f47c-eb87-520c-82c5-bf8dc4ed877d',E'Metadatos estructurales · pág. 53',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Contenido esperado: Información sobre el nivel de acceso a la variable.\nInstrucciones: Indicar el nivel de acceso a la variable en cumplimiento con lo dispuesto en el marco regulatorio\nque corresponda.\nEjemplo: Variable de uso público sin información considerada como confidencial.\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; security).\nElemento: 36 NOTAS O COMENTARIOS SOBRE LA VARIABLE\n                                    Condición de llenado: Opcional\nDescripción: Información adicional de la variable.\nContenido esperado: Información adicional acerca de las variables o los datos que contienen.\nInstrucciones: Documentar brevemente si existe información relevante y/o adicional que las y los usuarios\nnecesiten saber sobre las variables.\nEjemplos:\n      Nueva variable resultado de la actualización del instrumento de captación (versión 2021).\n      Datos preliminares\n      Datos definitivos\n      Datos ajustados\n      Datos corregidos\nEstándar de referencia: DDI CodeBook 2.0 (Variable description &gt; notes).</pre></div></section>',E'anexo',51,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos estructurales',E'Metadatos estructurales',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'8bc05b42-d398-59b1-989d-a03dd2699037',E'Metadatos descriptivos · pág. 54',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Descripciones, instrucciones, contenido esperado, condición de llenado y estándar de referencia de la\nespecificación de metadatos descriptivos para la representación estandarizada de los documentos\ntécnicos y conceptuales que dan soporte a los Procesos de Producción.\nA continuación, se detallan las descripciones, instrucciones, contenido esperado, condición de llenado y\nestándar de referencia y ejemplos de documentación para cada uno de los elementos que conforman la\nespecificación de metadatos descriptivos de los documentos técnicos y conceptuales que dan soporte a los\nProcesos de Producción que se describe en el Anexo III de la Norma Técnica, el cual fue adaptado a partir de\nla especificación de la Iniciativa de Metadatos Dublín Core (DCMI) versión 1.1. Esta sección aplica a todos los\nProcesos de Producción.\nPara documentar los metadatos existen elementos obligatorios, recomendados y opcionales. El llenado de los\nelementos obligatorios es indispensable para concluir la etapa de captura y edición, y continuar con la revisión,\nvalidación y autorización de los metadatos. Por otro lado, los elementos recomendados y opcionales pueden\nincrementar el valor de los metadatos.\nSección: Descripción de los materiales de soporte conceptual y metodológico.\nApartado: Identificación.\nElemento: 1 TÍTULO DEL DOCUMENTO O MATERIAL DE REFERENCIA\n                                    Condición de llenado: Obligatorio\nDescripción: Nombre del documento o material de referencia.\nContenido esperado: Título del documento o recurso de información.\nInstrucciones: Documentar el nombre de cada uno de los materiales de referencia incluidos en la\ndocumentación de metadatos.\nEjemplo: Cuestionario de Ocupación y Empleo (Ampliado).\nEstándar de referencia: Dublin Core Metadata Initiative (title).\nElemento: 2 FUENTE\n                                    Condición de llenado: Recomendado\nDescripción: Referencia de la fuente de información del material de referencia.\nContenido esperado: Fuente del documento o recurso de información.\nInstrucciones: Documentar la fuente de información de cada uno de los materiales de referencia incluidos en\nla documentación de metadatos.\nEjemplo: Encuesta Nacional de Ocupación y Empleo.\nEstándar de referencia: Dublin Core Metadata Initiative (source).</pre></div></section>',E'anexo',52,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'b860ae01-ab73-525c-91a4-edc2cc21e8db',E'Metadatos descriptivos · pág. 55',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Elemento: 3 TIPO\n                                    Condición de llenado: Obligatorio\nDescripción: Tipo de documento o material de referencia. Se deberá usar la lista de vocabulario controlado.\nContenido esperado: Tipo del documento o recurso de información.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. Deberá registrarse de\nconformidad con las siguientes categorías:\n             Audio\n             Base de datos\n             Catálogo o clasificador\n             Cuestionario o instrumento de captación\n             Decreto\n             Diseño conceptual\n             Documento metodológico\n             Documento técnico\n             Foto\n             Glosario\n             Guía\n             Informe de resultados\n             Instructivo\n             Ley\n             Manual\n             Mapa o Sistema de Información Geográfica\n             Norma\n             Principios\n             Recomendaciones\n             Reglamento\n             Sitio Web\n             Tabulado\n             Video\n             Otro\nEjemplo: Cuestionario o instrumento de captación.\nEstándar de referencia: Dublin Core Metadata Initiative (type).\nElemento: 4 FORMATO\n                                    Condición de llenado: Obligatorio\nDescripción: Formato del archivo del material de referencia. Se deberá usar la lista de vocabulario controlado.\nContenido esperado: Formato del documento o recurso de información.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. Deberá registrarse de\nconformidad con las siguientes categorías de acuerdo con la extensión del archivo del recurso de información:\n             ASCII\n             BIL\n             CSV\n             DOC o DOCX (Microsoft Word)\n             DWG</pre></div></section>',E'anexo',53,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'70f049b2-76e7-5f91-bd9a-05e15d6f257f',E'Metadatos descriptivos · pág. 56',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">             GPKG (GeoPackage)\n             Geo PDF\n             GIF\n             GRID\n             HTML\n             JPEG\n             JSON\n             MSG\n             PDF\n             PNG\n             PPT o PPTX (Microsoft Power point)\n             RAR (archivo empacado)\n             RDF\n             SHP\n             TIFF\n             TXT\n             XML\n             XLS o XLSX (Microsoft Excel)\n             ZIP (carpeta comprimida)\nEjemplo: PDF.\nEstándar de referencia: Dublin Core Metadata Initiative (format).\nElemento: 5 IDENTIFICADOR DEL DOCUMENTO O MATERIAL DE REFERENCIA\n                                    Condición de llenado: Recomendado\nDescripción: Identificador del material de referencia, si existe.\nContenido esperado: Código identificador del documento o recurso de información.\nInstrucciones: Indicar el código de identificación del material de referencia del recurso de información.\nEjemplo: COE-2016.\nEstándar de referencia: Dublin Core Metadata Initiative (identifier).\nElemento: 6 FECHA\n                                    Condición de llenado: Obligatorio\nDescripción: Fecha de creación del material de referencia, indicando día, mes y año (DD/MM/AAAA).\nContenido esperado: Fecha elaboración del documento o recurso de información.\nInstrucciones: Indicar la fecha de creación del material de referencia en formato DD/MM/AAAA.\nEjemplo: 2016.\nEstándar de referencia: Dublin Core Metadata Initiative (date).</pre></div></section>',E'anexo',54,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'cb072cff-0628-5851-8ab1-a9b0b2d51d2e',E'Metadatos descriptivos · pág. 57',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Elemento: 7 IDIOMA\n                                    Condición de llenado: Recomendado\nDescripción: Idioma principal del contenido del material de referencia. Se deberá usar la lista del vocabulario\ncontrolado basado en ISO 639-3 para seleccionar el idioma.\nContenido esperado: Idioma del documento o recurso de información.\nInstrucciones: Seleccionar del catálogo disponible, la categoría que corresponda. Deberá registrarse de\nconformidad con las siguientes categorías:\n             Alemán\n             Español\n             Francés\n             Inglés\n             Japonés\n             Portugués\nEjemplo: español.\nEstándar de referencia: Dublin Core Metadata Initiative (language).\nApartado: Propiedad intelectual.\nElemento: 8 AUTOR\n                                    Condición de llenado: Obligatorio\nDescripción: Institución o personas responsables del contenido del material de referencia.\nContenido esperado: Nombre del autor del documento o recurso de información.\nInstrucciones: Indicar el nombre de la institución o autor del material de referencia.\nEjemplo: INEGI.\nEstándar de referencia: Dublin Core Metadata Initiative (creator).\nElemento: 9 EDITOR\n                                    Condición de llenado: Recomendado\nDescripción: Institución o personas responsables de la edición del material de referencia.\nContenido esperado: Nombre institución o personas responsables de la edición del documento o recurso de\ninformación.\nInstrucciones: Indicar el nombre de la institución o personas responsables de la edición del material de\nreferencia.\nEjemplo: INEGI.\nEstándar de referencia: Dublin Core Metadata Initiative (publisher).\nElemento: 10 COLABORADORES</pre></div></section>',E'anexo',55,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'72854586-74f5-55d0-b44f-ec868841a560',E'Metadatos descriptivos · pág. 58',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                    Condición de llenado: Recomendado\nDescripción: Institución o personas responsables que contribuyeron a la elaboración del contenido del\nmaterial de referencia.\nContenido esperado: Colaboradores del documento o recurso de información.\nInstrucciones: Indicar el nombre de la institución o personas que contribuyen a la elaboración del material de\nreferencia.\nEjemplo: STPS.\nEstándar de referencia: Dublin Core Metadata Initiative (contributor).\nElemento: 11 DERECHOS\n                                    Condición de llenado: Recomendado\nDescripción: Información sobre los derechos de propiedad intelectual del material de referencia. Puede incluir\ninformación sobre términos y condiciones de acceso a un recurso.\nContenido esperado: Información sobre los derechos de propiedad intelectual del documento o recurso de\ninformación.\nInstrucciones: Indicar el nombre de la institución o personas que tienen los derechos de la propiedad\nintelectual del material de referencia.\nEste elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción.\nEjemplo: Derechos reservados © INEGI.\nEstándar de referencia: Dublin Core Metadata Initiative (rights).\nApartado: Contenido.\nElemento: 12 DESCRIPCIÓN DEL CONTENIDO\n                                    Condición de llenado: Obligatorio\nDescripción: Resumen del contenido del material de referencia.\nContenido esperado: Descripción del contenido del documento o recurso de información.\nInstrucciones: Incorporar un breve resumen sobre el contenido del material de referencia. Incorporar una\nbreve relatoría de los elementos que dan sustento histórico y evolución teórica y metodológica, entre otros, al\nProceso de Producción de referencia, que sirven para comprender o valorar su alcance.\nEjemplo:\nLa versión ampliada sólo se levanta el primer trimestre de cada año y la básica el resto de los trimestres. Al\naplicar la versión básica se aprovecha para levantar lo que en el INEGI se han denominado módulos\nespeciales. Los módulos son cuestionarios que se aplican a una submuestra de una encuesta en particular; a\ntravés de los módulos se profundiza en una temática específica. En el caso de la ENOE, por ejemplo, ha sido\nposible ahondar en temas como empleo y seguridad social; educación, capacitación y empleo; trabajo infantil;\ndisponibilidad y uso de tecnologías de la información en los hogares; entre otros.</pre></div></section>',E'anexo',56,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'5f72c39e-af8f-58d9-b6cc-6231b36edb43',E'Metadatos descriptivos · pág. 59',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Estándar de referencia: Dublin Core Metadata Initiative (description).\nElemento: 13 TEMAS\n                                    Condición de llenado: Obligatorio\nDescripción: Temas abordados en el material de referencia.\nContenido esperado: Temas principales del documento o recurso de información.\nInstrucciones: Indicar los temas principales contenidos en el material de referencia.\nEjemplo:\n    I.     Condición de ocupación\n    II.    No ocupados\n    III.   Contexto laboral\n    IV.    Características de la unidad económica\n    V.     Jornada y regularidad laboral\n    VI.    Ingresos y atención médica\n    VII.   Trabajo secundario\n    VIII.  Búsqueda de otro trabajo\n    IX.    Antecedentes laborales\n    X.     Apoyos económicos\n    XI.    Otras actividades\nEstándar de referencia: Dublin Core Metadata Initiative (subject).\nElemento: 14 COBERTURA\n                                    Condición de llenado: Recomendado\nDescripción: Características de cobertura espacial y temporal del material de referencia.\nContenido esperado: Cobertura geográfica y temporal del documento o recurso de información.\nInstrucciones: En caso de ser necesario indicar la referencia del espacio geográfico y temporal al que\ncorresponde el contenido del material de referencia.\nEjemplo: Primer trimestre de los años 2016 a 2021.\nEstándar de referencia: Dublin Core Metadata Initiative (coverage).\nElemento: 15 DOCUMENTOS RELACIONADOS\n                                    Condición de llenado: Recomendado\nDescripción: Identificador de otros recursos de información relacionados con el recurso actual. Este elemento\npermite enlazar los recursos relacionados y sus descripciones.\nContenido esperado: Otros documentos o recursos de información relacionados.\nInstrucciones: Documentar los recursos relacionados con el material de referencia documentado.</pre></div></section>',E'anexo',57,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'f3d9a449-62f5-58b2-842d-2a54c8bfb119',E'Metadatos descriptivos · pág. 60',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Este elemento podría requerir actualizarse en correspondencia con la ejecución de un nuevo ciclo del Proceso\nde Producción\nEjemplos:\n      Cuestionario Sociodemográfico de la ENOE. Cuarta versión. Trimestres: II de 2016 al II de 2021.\n      Cuestionario Básico de Ocupación y Empleo. Quinta versión. Trimestres: II, III y IV de 2016, 2017,\n       2018, 2019, 2020 y II de 2021\nEstándar de referencia: Dublin Core Metadata Initiative (relation).</pre></div></section>',E'anexo',58,E'Guía de implementación · Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Metadatos descriptivos',E'21767166-96f6-51f4-ba54-dda32288b6fe') on conflict(id) do nothing;
